/* WRLDLINE History — global timeline */
(() => {
  const H = window.WL_HISTORY;
  if (!H) return;
  H.events.push(
    {year:-10000, label:"10000 ق.م", title:"نهاية العصر الجليدي وبداية الهولوسين", body:"قبل نحو عشرة آلاف سنة ارتفعت حرارة الأرض وتراجعت الصفائح الجليدية، فتغيّرت السواحل والأنهار والغطاء النباتي في معظم القارات. أتاح المناخ الجديد بيئات أصلح للاستقرار والزراعة، فبدأت جماعات بشرية تنتقل تدريجياً من الصيد والجمع إلى استغلال أكثر تنظيماً للأرض والماء. لم يكن التحول واحداً ولا متزامناً، لكنه مهّد لكل ما جاء بعده من قرى ومدن ودول.", region:"global", theme:"environment", entity:null},
    {year:-9500, label:"9500 ق.م", title:"أريحا: أولى القرى الزراعية في وادي الأردن", body:"في موقع أريحا ظهرت نحو 9500 ق.م واحدة من أقدم القرى المستقرة المعروفة، ببيوت حجرية ومخازن حبوب وأسوار تعكس تنظيماً جماعياً غير مسبوق. يعني ذلك أن الاستقرار الزراعي سبق المدن والدول بزمن طويل، وأن الإنسان بدأ يغيّر بيئته بدل أن يتبعها فقط. من تجارب كهذه نشأت قرى كبرى في المشرق، تفرّعت فيها الحرف والتجارة والطقوس، وهي جذور الحياة الحضرية اللاحقة.", region:"middle-east", theme:"economy", entity:null},
    {year:-9000, label:"9000 ق.م", title:"غوبكلي تبه: العبادة قبل الزراعة", body:"على تلال جنوب شرق الأناضول أقامت جماعات من الصيادين والجامعين دوائر من أعمدة حجرية ضخمة منقوشة بصور حيوانات، تعود إلى نحو 9000 ق.م. هذه المنشآت أقدم من الزراعة ومن الفخار في المنطقة، وهي تدل على قدرة على التنظيم والعمل الجماعي بلا دولة ولا مدن. غيّرت الاكتشافات فرضيات كثيرة عن تسلسل الحضارة، إذ أظهرت أن الدافع الرمزي والديني قد يسبق التحول الاقتصادي.", region:"middle-east", theme:"religion", entity:"tr"},
    {year:-8000, label:"8000 ق.م", title:"غرق سهل ساهول وعزل أستراليا", body:"مع ارتفاع مستوى البحار بعد العصر الجليدي غرق الجسر البري الذي كان يصل أستراليا بغينيا الجديدة، وتشكّلت مضيق توريس وبحر أرافورا نحو 8000 ق.م. انعزلت بذلك مجتمعات السكان الأصليين في أستراليا عن جيرانها الشماليين، واستمرت في تطوير معرفة دقيقة بالأرض والنبات والحيوان. هذا الانفصال الجغرافي يفسّر تنوّع اللغات والثقافات في أوقيانوسيا، ويذكّر بأن الجغرافيا تصنع التاريخ بقدر ما يصنعه البشر.", region:"oceania", theme:"environment", entity:null},
    {year:-7500, label:"7500 ق.م", title:"تشاتال هويوك: قرية بلا شوارع", body:"في سهل قونية بوسط الأناضول قامت نحو 7500 ق.م مستوطنة كثيفة السكان تُعرف اليوم بتشاتال هويوك، ببيوت متلاصقة يدخل إليها الناس من سطوحها، وجدران تحمل رسوماً ونقوشاً. تدل القرية على أن التحضر لا يحتاج بالضرورة إلى شوارع ومعابد ضخمة، وأن الحياة الجماعية يمكن أن تنظم نفسها حول المسكن والعمل والطقس. بقيت هذه التجربة نموذجاً مبكراً لتعقيد اجتماعي نشأ من الزراعة قبل ظهور الكتابة والدولة.", region:"middle-east", theme:"culture", entity:"tr"},
    {year:-7000, label:"7000 ق.م", title:"زراعة الدخن في وادي النهر الأصفر", body:"في مواقع مثل جياهو وسط الصين بدأت نحو 7000 ق.م زراعة الدخن وتدجين الخنزير، مع فخار مبكر ومزامير عظمية تدل على حياة طقسية واجتماعية غنية. شكّلت هذه البدايات أساساً اقتصادياً لشمال الصين، حيث نشأت لاحقاً مجتمعات كثيفة ثم دول أولى. يبيّن المثال أن الزراعة ظهرت في مراكز مستقلة عدة، وأن المسارات الصينية إلى الحضارة لم تكن نسخة من مسارات المشرق بل قامت على محاصيل ومناخ مختلفين.", region:"asia", theme:"economy", entity:"cn"},
    {year:-6500, label:"6500 ق.م", title:"رعاة الصحراء الكبرى قبل التصحر", body:"بين نحو 6500 و3000 ق.م كانت الصحراء الكبرى أرضاً خضراء ببحيرات وأنهار موسمية، رعتها جماعات من مربي الماشية تركت نقوشاً وأدوات وحفريات تكشف شبكات تنقل واسعة. مثّل هذا العصر الرطب جسراً بين شمال أفريقيا ووادي النيل وجنوب الصحراء، انتقلت عبره التقنيات والمحاصيل واللغات. عندما تغيّر المناخ لاحقاً وبدأ التصحر، انسحب السكان نحو النيل والواحات، وهو تحول بيئي عميق شكّل خريطة المنطقة حتى اليوم.", region:"africa", theme:"economy", entity:null},
    {year:-6000, label:"6000 ق.م", title:"الريّ في بلاد الرافدين", body:"نحو 6000 ق.م بدأت مجتمعات جنوب بلاد الرافدين تحفر قنوات لتحويل مياه دجلة والفرات إلى حقولها، في خطوة تجاوزت الزراعة المعتمدة على المطر. أنتج الري فوائض غذائية أكبر وسمح بكثافة سكانية أعلى، لكنه فرض أيضاً تنظيماً جماعياً للعمل وصيانة الشبكات، فظهرت سلطات تنظيمية قبل الدولة المكتوبة. هكذا ربطت تجربة الرافدين بين التحكم في الماء وقيام المؤسسات، وهو رابط بقي محورياً في تاريخ المنطقة.", region:"middle-east", theme:"technology", entity:"iq"},
    {year:-5000, label:"5000 ق.م", title:"صهر النحاس في البلقان", body:"في مواقع بشرق أوروبا يعود بعضها إلى نحو 5000 ق.م عُثر على أفران وخبث نحاسي وأدوات معدنية، وهي من أقدم شواهد صهر المعدن في العالم. مثّل النحاس مادة جديدة تتطلب حرارة عالية ومعرفة بالتعدين والتشكيل، فبدأت تتشكل حرف متخصصة وشبكات تبادل للمواد النادرة. لم يكن المعدن مجرد أداة عملية، بل صار رمزاً للمكانة، ومهّد الطريق لعصر البرونز الذي ربط اقتصاديات الشرق الأدنى وأوروبا.", region:"europe", theme:"technology", entity:null},
    {year:-4500, label:"4500 ق.م", title:"نقوش الصحراء الكبرى", body:"على صخور الصحراء الكبرى في ليبيا والجزائر والنيجر ترك رعاة ما قبل التاريخ آلاف النقوش والرسوم التي تصوّر أبقاراً وزرافات وبشراً في مشاهد صيد ورقص. تعود أقدم طبقاتها إلى نحو 4500 ق.م وأكثر، وتكشف عالماً حياً قبل التصحر، وتُقرأ اليوم كأرشيف بصري لمعتقدات وطقوس وأساليب حياة اندثرت. أهمية هذه النقوش أنها تروي تاريخ أفريقيا الداخلي بلغة أهلها، لا عبر كتابات الغزاة والتجار اللاحقين.", region:"africa", theme:"culture", entity:null},
    {year:-4400, label:"4400 ق.م", title:"الزراعة على ضفاف النيل", body:"نحو 4400 ق.م انتشرت في مصر العليا والوسطى زراعة القمح والشعير مع الرعي والسمك، في مستوطنات مثل البداري تعكس علاقة وثيقة بإيقاع فيضان النيل. جعل الفيضان السنوي الأرض خصبة بلا حاجة إلى شبكات ري معقدة، فقام اقتصاد زراعي مستقر نسبياً مع فائض يسمح بالحرف والتجارة. من هذا الأساس المادي نشأت لاحقاً المقاطعات ثم المملكة الموحدة، التي ربطت وادي النيل في نظام سياسي واحد دام آلاف السنين.", region:"africa", theme:"economy", entity:"eg"},
    {year:-4000, label:"4000 ق.م", title:"العجلة والمحراث في المشرق", body:"نحو 4000 ق.م ظهرت في بلاد الرافدين وشرق أوروبا أولى العربات ذات العجلات والمحاريث التي تجرها الحيوانات، في تحوّل تقني غيّر الزراعة والنقل معاً. زاد المحراث مساحة الأرض المزروعة وأتاح استغلال تربة أعمق، بينما وسعت العربة نقل المحاصيل والمواد الثقيلة وربطت الأسواق. هكذا تراكمت الفوائض واتسعت شبكات التبادل، وهي شروط مادية لقيام المدن ثم الدولة المنظمة في الألفية التالية.", region:"middle-east", theme:"technology", entity:null},
    {year:-3500, label:"3500 ق.م", title:"أوروك: أول ثورة حضرية", body:"نحو 3500 ق.م تحوّلت أوروك في جنوب بلاد الرافدين إلى مدينة كبيرة بمعابد ضخمة وأحياء حرفية وأسواق، تجاوز سكانها ما عُرف قبله من قرى زراعية. تطلب هذا التجمع كتابة أولية للحساب وتنظيم العمل وتوزيع الفائض، فظهرت أختام ورموز ثم ألواح طينية. مثّلت أوروك نموذجاً انتشر في المشرق عبر التجارة والاستيطان، وأثبتت أن المدينة ليست حجماً فقط بل نظام إدارة واقتصاد ورمز.", region:"middle-east", theme:"economy", entity:"iq"},
    {year:-3200, label:"3200 ق.م", title:"اختراع الكتابة المسمارية في سومر", body:"نحو 3200 ق.م بدأ كتّاب سومر في جنوب بلاد الرافدين يسجّلون الحبوب والمواشي والعمل على ألواح طينية بأسلوب صوري تطور إلى الكتابة المسمارية. لم تكن الكتابة أدباً في بدايتها، بل أداة محاسبة وإدارة، ثم اتسعت لتشمل القوانين والرسائل والملاحم. بها انتقلت المعرفة من الذاكرة الجماعية إلى السجل الدائم، فصار ممكناً تراكم القانون والعلم والتاريخ عبر الأجيال، وهو أحد أعمق التحولات في تاريخ البشرية.", region:"middle-east", theme:"knowledge", entity:"iq"},
    {year:-3100, label:"3100 ق.م", title:"توحيد مصر العليا والسفلى", body:"نحو 3100 ق.م ظهرت في مصر دولة موحدة ترمز إليها لوحة نارمر وأختام وأسماء ملوك، تربط الدلتا بالجنوب في نظام حكم واحد. قامت هذه الدولة على النيل والفيضان والزراعة والكتابة الهيروغليفية، وبنَت مؤسسات للجباية والعمل الجماعي والطقوس الملكية. منحها العزل الجغرافي استقراراً طويلاً، فصارت مصر من أطول الكيانات السياسية عمراً، ونموذجاً لدولة مركزية تقوم على النهر والكتابة والدين الملكي.", region:"africa", theme:"politics", entity:"eg"},
    {year:-3000, label:"3000 ق.م", title:"مدن وادي السند", body:"نحو 3000 ق.م بدأت في وادي السند مدن كبيرة مثل هارابا وموهنجو دارو تتشكّل، وبلغت ذروتها بعد 2600 ق.م بشوارع مرصوفة وشبكات صرف وحُفر تخزين وطوب موحّد القياس. تدل هذه التفاصيل على تخطيط مسبق وإدارة جماعية واقتصاد زراعي وتجاري متصل ببلاد الرافدين والخليج. لم تُقرأ كتابة السند حتى الآن، لكن آثارها تكفي لبيان حضارة حضرية أصلية لا تقل تنظيماً عن معاصراتها. اندثرت مدنها نحو 1900 ق.م لأسباب بيئية واقتصادية ما تزال موضع بحث.", region:"asia", theme:"economy", entity:"in"},
    {year:-2900, label:"2900 ق.م", title:"كارال: حضارة بيروفية بلا معابد", body:"في وادي سوبي على ساحل بيرو قامت نحو 2900 ق.م مدينة كارال ضمن حضارة نورتي تشيكو، بمنصات وأهرامات مدرّجة وساحات دائرية وقنوات ري، من دون فخار أو كتابة معروفة. يدل هذا على أن التحضر والبناء الجماعي لم يكونا حكراً على الشرق الأدنى، وأن مجتمعات الأنديز طوّرت مسارها الخاص القائم على الزراعة المروية والتبادل. أعادت اكتشافات كارال ترتيب فهم نشأة المدن في الأمريكتين قبل الأولمك والإنكا بقرون طويلة.", region:"americas", theme:"culture", entity:null},
    {year:-2600, label:"2600 ق.م", title:"الهرم الأكبر في الجيزة", body:"نحو 2600 ق.م أُنجز هرم خوفو في الجيزة، أكبر بناء حجري في العالم القديم، بارتفاع تجاوز مئة وأربعين متراً وحجارة يعجز النقل الحديث البسيط عن محاكاتها بسهولة. يعكس البناء قدرة الدولة على حشد العمل وتنظيم الإمدادات وقياس الزمن والنجوم، أكثر من كونه مجرد قبر ملكي. صار الهرم رمزاً لدولة فرعونية بلغت ذروة مركزيتها، ولقدرة التقنية والمعتقد على إنتاج أثر باقٍ آلاف السنين.", region:"africa", theme:"culture", entity:"eg"},
    {year:-2334, label:"2334 ق.م", title:"سرجون الأكدي وأول إمبراطورية", body:"نحو 2334 ق.م وحّد سرجون الأكدي مدن سومر تحت سلطة مركزية، وأسس دولة امتدت من الخليج إلى سوريا، تُعد من أوائل الإمبراطوريات في التاريخ. اعتمدت على جيش دائم ولغة إدارية موحدة وولاة وشبكة طرق وتجارة، فأنشأت فكرة السيادة على شعوب متعددة لا على مدينة واحدة. بقيت ذكرى سرجون نموذجاً للسلطة الشاملة في أدب المشرق، وأثبتت أن التنوع يمكن أن يُدار بمركز قوي حين تتوفر البنية والاتصال.", region:"middle-east", theme:"politics", entity:"iq"},
    {year:-2200, label:"2200 ق.م", title:"جفاف 4.2 ألف سنة وانهيار الدول", body:"نحو 2200 ق.م ضرب الشرق الأدنى وجنوب آسيا وأجزاء من أفريقيا جفاف طويل يُعرف بحدث 4.2 ألف سنة، تزامن مع انهيار الدولة الأكدية وتفكك مستوطنات في وديان أخرى. لم يكن المناخ وحده سبباً، لكنه ضغط على الزراعة والجباية فكشف هشاشة الأنظمة المركزية أمام أزمة غذاء ممتدة. تُقرأ هذه الحادثة اليوم كأول مثال موثق لكيف يمكن لتغيّر المناخ أن يعيد رسم الخريطة السياسية، وهو درس متكرر في التاريخ.", region:"global", theme:"environment", entity:null},
    {year:-2100, label:"2100 ق.م", title:"قانون أور-نمو", body:"نحو 2100 ق.م صدر في مدينة أور قانون منسوب إلى الملك أور-نمو، يُعد من أقدم مجموعات القوانين المكتوبة التي وصلتنا، ويحدد تعويضات عن الجرائم والسرقة والأذى الجسدي. لم يكن القانون مجرد عقاب، بل وسيلة لتقييد الانتقام الخاص وتثبيت توقعات الناس في مجتمع حضري متشابك. مهّد هذا النص لقوانين لاحقة مثل قانون حمورابي، وأسّس فكرة أن السلطة تُشرّع قواعدها وتعلنها بدل أن تحكم بالمزاج.", region:"middle-east", theme:"rights", entity:"iq"},
    {year:-2000, label:"2000 ق.م", title:"اكتمال ستونهنج", body:"نحو 2000 ق.م اكتملت في سهل سالزبري بإنكلترا حلقة ستونهنج الحجرية الكبرى، بعد مراحل بناء بدأت قبل ذلك بقرون، مع ترتيب حجارة يرتبط بالشمس والانقلابين الصيفي والشتوي. يعكس البناء معرفة فلكية وهندسية وقدرة على نقل أحجار ضخمة من مسافات بعيدة، وتنظيماً اجتماعياً واسعاً في مجتمع لا يعرف الكتابة. يبقى ستونهنج دليلاً على أن أوروبا ما قبل التاريخ صنعت معماراً طقسياً معقداً بمواردها الخاصة.", region:"europe", theme:"religion", entity:"gb"},
    {year:-1900, label:"1900 ق.م", title:"قصور كريت المينوية", body:"نحو 1900 ق.م ظهرت في كريت قصور كبيرة مثل كنوسوس وفايستوس، بمخازن ضخمة وفنون جدارية ونظام كتابة يُعرف بالخط الخطي أ. قام اقتصادها على الزيتون والكرمة والتجارة البحرية مع مصر والمشرق، ما جعل الجزيرة مركزاً بحرياً لا إمبراطورية أرضية. تشير القصور إلى مجتمع طبقي منظم بلا تحصينات كبيرة، وهو ما يثير نقاشاً مستمراً حول طبيعة السلطة المينوية ومصادر قوتها.", region:"europe", theme:"culture", entity:"gr"},
    {year:-1750, label:"1750 ق.م", title:"قانون حمورابي", body:"نحو 1750 ق.م نُقش قانون حمورابي على مسلة حجرية في بابل، يضم مئات المواد في العقود والديون والزواج والملكية والعمل والجراحات، مع عقوبات تتفاوت بحسب المكانة الاجتماعية. لم يكن القانون مجرد تنظيم محلي، بل أداة لتوحيد مملكة متعددة الأعراق تحت قاعدة مكتوبة ومعلنة، وصار لاحقاً رمزاً لفكرة العدالة المدوّنة. تأثيره الأعمق أنه جعل القانون نصاً عاماً يمكن الرجوع إليه، لا مجرد أمر يصدره الحاكم.", region:"middle-east", theme:"rights", entity:"iq"},
    {year:-1600, label:"1600 ق.م", title:"أسرة شانغ وعظام النبوءة", body:"نحو 1600 ق.م قامت أسرة شانغ في وادي النهر الأصفر، وتركت آثار مدن مثل آنيانغ وقبوراً ملكية وأواني برونزية متقنة، وأهم من ذلك آلاف عظام النبوءة المنقوشة بأسئلة للملوك والأسلاف. هذه النقوش أقدم شواهد مكتوبة معروفة في الصين، وتكشف دولة مركزية ذات طقوس وتنظيم عسكري وجباية. من هذا الأساس نشأ التقليد الصيني في ربط الحكم بالكهانة والأخلاق الكونية، ثم تبلور لاحقاً في فكرة تفويض السماء.", region:"asia", theme:"knowledge", entity:"cn"},
    {year:-1550, label:"1550 ق.م", title:"المملكة الحديثة في مصر", body:"نحو 1550 ق.م طرد ملوك طيبة الهكسوس وأسسوا المملكة الحديثة، فبدأت مصر مرحلة توسع عسكري وإداري بلغت فيه حدودها بلاد النهرين وشمال السودان. رافق ذلك جيش نظامي وعربات حربية وديوان مركزي ومعابد ضخمة وعلاقات دبلوماسية بالدول المجاورة. صارت مصر قوة كبرى في شرق المتوسط، وأثبتت أن الوحدة النهرية يمكن أن تتحول إلى مشروع خارجي حين تتوفر الموارد والتنظيم والإرادة السياسية.", region:"africa", theme:"politics", entity:"eg"},
    {year:-1500, label:"1500 ق.م", title:"التراتيل الفيدية في الهند", body:"بين نحو 1500 و1000 ق.م نُظمت في شمال الهند تراتيل باللغة السنسكريتية عُرفت بالفيدا، تُنشد في الطقوس وتصف آلهة وعالماً من القبائل والمراعي والأنهار. نُقلت هذه النصوص شفهياً بدقة مذهلة قبل أن تُدوّن بعد قرون، وشكّلت أساساً للدين البراهمي ثم الهندوسية، ولنظام اجتماعي طبقي تبلور لاحقاً. أهمية الفيدا أنها أرشيف لغوي وثقافي نادر عن مجتمع لم يعرف الكتابة في مرحلته الأولى، ومصدر لفهم تشكّل جنوب آسيا.", region:"asia", theme:"religion", entity:"in"},
    {year:-1350, label:"1350 ق.م", title:"إخناتون وعبادة آتون", body:"نحو 1350 ق.م أعلن الملك إخناتون تفضيل قرص الشمس آتون على آلهة مصر التقليدية، ونقل العاصمة إلى موقع جديد سمّاه أخيتاتون، وأمر بأساليب فنية أكثر واقعية. مثّلت التجربة أول محاولة موثقة لتغيير دين دولة من القمة، لكنها واجهت مقاومة الكهنة والنخب، فمحا خلفاؤه آثارها وأعادوا العبادة القديمة. تبقى الحادثة مثالاً على حدود الإصلاح الديني المفروض من السلطة، وعلى هشاشة الشرعية حين تنفصل عن المؤسسات القائمة.", region:"africa", theme:"religion", entity:"eg"},
    {year:-1200, label:"1200 ق.م", title:"انهيار العصر البرونزي", body:"نحو 1200 ق.م انهارت في شرق المتوسط ممالك الحيثيين وأوغاريت ومدن ميكيناي، وتراجعت شبكات التجارة البرونزية، في سلسلة أزمات تُعرف بانهيار العصر البرونزي. تُنسب الأزمة إلى هجمات شعوب البحر والجفاف والزلازل واضطراب التجارة، ويُرجّح الباحثون تداخل هذه العوامل بدل عامل واحد. أعقب الانهيار عصر حديدي أكثر محلية، ظهرت فيه فينيقيا وإسرائيل وممالك جديدة، وتغيّرت تقنيات السلاح والكتابة والتنظيم السياسي في المنطقة كلها.", region:"middle-east", theme:"war", entity:null},
    {year:-1100, label:"1100 ق.م", title:"الأولمك في خليج المكسيك", body:"نحو 1100 ق.م قامت على ساحل خليج المكسيك حضارة الأولمك، التي تركت رؤوساً حجرية ضخمة ومنصات طقسية ونظام كتابة ورمز مبكر، وتجارة تمتد إلى مرتفعات المكسيك. تُعد الأولمك من أولى الحضارات المعقدة في أمريكا الوسطى، وأثرت في شعوب لاحقة مثل المايا والزابوتك في المعتقد والفن وتنظيم المدن. يدل مسارها المستقل على أن الحضارة ليست اختراعاً واحداً انتقل من مكان إلى آخر، بل تجارب متعددة نشأت في بيئات مختلفة.", region:"americas", theme:"culture", entity:"mx"},
    {year:-1000, label:"1000 ق.م", title:"اللابيتا ووصول البشر إلى فيجي وتونغا", body:"نحو 1000 ق.م وصلت جماعات تحمل فخار اللابيتا المزخرف إلى فيجي وتونغا وساموا، في أوسع انتشار بشري عبر المحيط الهادئ قبل العصر الحديث. اعتمد هؤلاء على القوارب الشراعية والملاحة بالنجوم والتيارات ومعرفة دقيقة بالرياح، ونقلوا معهم الزراعة والحيوانات واللغة. مثّل هذا التوسع أساس المجتمعات البولينيزية لاحقاً، ويُعد شاهداً على قدرة الإنسان على استيطان أشد البيئات عزلة بلا دولة ولا كتابة.", region:"oceania", theme:"exploration", entity:null},
    {year:-1000, label:"1000 ق.م", title:"قيام مملكة كوش في النوبة", body:"نحو 1000 ق.م برزت مملكة كوش في النوبة حول نباتا، بعد تراجع السيطرة المصرية، وطوّرت ثقافة خاصة جمعت تقاليد أفريقية ومصرية، ودفن الملوك في أهرامات حجرية صغيرة. قام اقتصادها على الذهب والتجارة عبر النيل والصحراء، وصارت قوة إقليمية قادرة على التدخل في مصر نفسها لاحقاً. تُظهر كوش أن وادي النيل لم يكن مصر وحدها، وأن أفريقيا الداخلية أنتجت دولاً ذات مؤسسات وفنون قبل الاتصال الأوروبي بقرون.", region:"africa", theme:"politics", entity:null},
    {year:-950, label:"950 ق.م", title:"الأبجدية الفينيقية تنتشر في المتوسط", body:"نحو 950 ق.م طوّر الفينيقيون في مدن مثل صور وصيدا أبجدية من نحو اثنتين وعشرين علامة، اختصرت الكتابة المسمارية والهيروغليفية إلى نظام سهل التعلم والتداول. انتشرت مع تجارتهم البحرية في المتوسط، واقتبسها اليونانيون ثم شعوب أخرى، فصارت أصلاً لمعظم الأبجديات المستخدمة اليوم. أهمية هذا التحول أنه جعل القراءة والكتابة ممكنة لجماعات أوسع من الكتبة المحترفين، فوسّع دائرة المعرفة والتجارة والتشريع.", region:"middle-east", theme:"knowledge", entity:null},
    {year:-900, label:"900 ق.م", title:"الجيش الآشري وآلة الحرب الأولى", body:"في القرن التاسع قبل الميلاد بنت آشور جيشاً دائماً مدرباً استخدم العربات الحربية والمجانيق وأبراج الحصار والترحيل الجماعي، ووسّع حدودها من العراق إلى الشام والأناضول. لم تكن القوة وحدها كافية، فقد اعتمدت الدولة على ولاة وجباية وطرق وشبكات استخبارات وبروباغندا ملكية منقوشة. أنتجت آشور نموذجاً مبكراً للإمبراطورية الإرهابية المنظمة، لكنه أظهر أيضاً هشاشة البناء القائم على القهر، فانهار بسرعة بعد ذروته.", region:"middle-east", theme:"war", entity:"iq"},
    {year:-800, label:"800 ق.م", title:"الأبجدية اليونانية وهوميروس", body:"نحو 800 ق.م اقتبس اليونانيون الأبجدية الفينيقية وأضافوا إليها حروف العلة، فصار للغة اليونانية نظام كتابة دقيق يخدم الشعر والفلسفة والقانون. في الفترة نفسها تُنسب إلى هوميروس ملحمتا الإلياذة والأوديسة، اللتان نُقلتا شفهياً ثم دوّنتا، وأسستا ذاكرة مشتركة للهوية اليونانية. الربط بين الأبجدية والملحمة يوضح كيف تصنع أدوات الكتابة هوية ثقافية، وكيف تحوّل الأسطورة إلى أساس تعليمي وسياسي لمدن متفرقة.", region:"europe", theme:"culture", entity:"gr"},
    {year:-776, label:"776 ق.م", title:"أول ألعاب أولمبية", body:"تُؤرّخ المصادر اليونانية أول ألعاب أولمبية إلى 776 ق.م في أولمبيا، حيث تنافس ممثلو المدن في العدو والمصارعة وسباق العربات أمام زيوس. لم تكن الألعاب ترفيهاً فقط، بل هدنة دينية ولحظة لتحديد الهوية المشتركة بين مدن تتنازع سياسياً، وكانت وحدات الزمن تُحسب بدوراتها. أعادت الألعاب الحديثة إحياء هذا التقليد في القرن التاسع عشر، فصارت رمزاً عالمياً للتنافس المنظم بعيداً عن الحرب.", region:"europe", theme:"culture", entity:"gr"},
    {year:-753, label:"753 ق.م", title:"تأسيس روما", body:"يؤرخ التقليد الروماني تأسيس المدينة إلى 753 ق.م على سبع تلال قرب نهر التيبر، في موقع يسهل عبوره ويطل على طرق الملح والتجارة. جمعت روما المبكرة بين ملكية وطقوس ومجلس شيوخ، ثم تحولت إلى جمهورية تتوسع بالحرب والتحالفات والمواطنة. لم تكن قوة روما نتيجة موقعها فقط، بل نتيجة قدرتها على استيعاب المهزومين في نظامها السياسي، وهي ميزة ساعدتها على بناء إمبراطورية دامت قروناً.", region:"europe", theme:"politics", entity:"it"},
    {year:-730, label:"730 ق.م", title:"الأسرة الخامسة والعشرون الكوشية في مصر", body:"نحو 730 ق.م قاد الملك الكوشي بيا حملة على مصر وأخضعها، فأسّس ملوك نباتا الأسرة الخامسة والعشرين التي حكمت وادي النيل حتى نحو 656 ق.م. أعاد هؤلاء الملوك بناء المعابد وترميم التقليد الفرعوني، ودمجوا رموز كوش ومصر في فنونهم وعقائدهم. تدل التجربة على حركة السلطة في اتجاه معاكس للمألوف، إذ حكم جنوبُ الوادي شمالَه، وتذكّر بأن الحدود الثقافية بين مصر والنوبة كانت أكثر سيولة مما توحي به الخرائط.", region:"africa", theme:"politics", entity:"eg"},
    {year:-660, label:"660 ق.م", title:"مكتبة آشور بانيبال في نينوى", body:"نحو 660 ق.م جمع الملك الآشوري آشور بانيبال في نينوى آلاف الألواح الطينية، ضمت ملحمة جلجامش ونصوصاً في الطب والنجوم والقانون والمعاجم. لم تكن المكتبة جمعاً عشوائياً، بل مشروع دولة لاحتكار المعرفة وتنظيمها ونسخها من مراكز أخرى. عندما سقطت نينوى احترق الأرشيف، لكن الطين المحروق حفظ النصوص، فاستعاد الباحثون في العصر الحديث جزءاً كبيراً من أدب بلاد الرافدين وعلمها بفضل تلك الكارثة نفسها.", region:"middle-east", theme:"knowledge", entity:"iq"},
    {year:-600, label:"600 ق.م", title:"الفلسفة تبدأ في ميليتوس", body:"نحو 600 ق.م بدأ مفكرون في مدينة ميليتوس الأيونية مثل طاليس وأنكسيمندريس يفسّرون الطبيعة بمبادئ داخلية لا بإرادة الآلهة، فبحثوا في أصل الأشياء والكون والظواهر الجوية. مثّل هذا التحول قطيعة معرفية مع التفسير الأسطوري، وأسّس تقليداً في النقد والحوار والبرهان تطور في أثينا ثم في العالم الهلنستي. أهمية ميليتوس أنها ربطت بين التجارة والانفتاح الثقافي والتفكير النظري، فأنتجت أول مدرسة فلسفية موثقة في التاريخ الأوروبي.", region:"europe", theme:"knowledge", entity:"gr"},
    {year:-550, label:"550 ق.م", title:"قورش يؤسس الإمبراطورية الأخمينية", body:"نحو 550 ق.م أسقط قورش الثاني مملكة الميديين وأسس الإمبراطورية الأخمينية في إيران، ثم ضمّ ليديا وبابل ومدن أيونيا، وبنى نظاماً يتسامح مع أديان الشعوب ويلغيه في إدارة محلية. اعتمد على ولاة وطرق بريدية وعملة ذهبية ولغة آرامية إدارية، فأنشأ إمبراطورية واسعة متعددة الثقافات. تُذكر في المصادر التوراتية بإعادة يهود بابل إلى القدس، ويُستشهد بها على أن الحكم الفعّال قد يقوم على التسامح لا على الإخضاع الثقافي.", region:"middle-east", theme:"politics", entity:"ir"},
    {year:-509, label:"509 ق.م", title:"قيام الجمهورية الرومانية", body:"في 509 ق.م أطاحت نخبة روما بالملكية وأقامت جمهورية ينتخب فيها قنصلان ومجلس شيوخ وجمعيات شعبية، في نظام يوازن السلطات ويحدد المدة. لم تكن الجمهورية ديمقراطية شاملة، إذ استبعدت النساء والعبيد وكثيراً من غير المواطنين، لكنها أنتجت مؤسسات وقوانين وقنوات صعود سياسي. بقيت تجربتها مرجعاً للفكر الجمهوري لاحقاً، وأثبتت أن استقرار الدولة يمكن أن يقوم على توزيع السلطة لا على شخص واحد.", region:"europe", theme:"politics", entity:"it"},
    {year:-500, label:"500 ق.م", title:"كونفوشيوس وتنظيم العلاقات الاجتماعية", body:"نحو 500 ق.م علّم كونفوشيوس في الصين أن إصلاح المجتمع يبدأ من تهذيب الفرد واحترام العلاقات: الحاكم والمحكوم، الأب والابن، الصديق والصديق. لم يقدّم نظاماً دينياً بالمعنى الضيق، بل أخلاقاً عملية تربط الاستقرار السياسي بسلوك النخبة ومسؤوليتها. اعتمدت دول صينية لاحقة تعاليمه في التعليم والامتحانات والإدارة، فصارت الكونفوشية إطاراً ثقافياً دائمياً في شرق آسيا، ومصدر جدل مستمر حول العلاقة بين الطاعة والإصلاح.", region:"asia", theme:"knowledge", entity:"cn"},
    {year:-480, label:"480 ق.م", title:"الحروب الفارسية اليونانية", body:"في 480 ق.م عبرت جيوش أحشويرش الأول إلى اليونان، فجرت معارك ثيرموبيلاي وسلاميس التي انتهت بتراجع الأسطول الفارسي، ثم بمعارك برية حاسمة في السنة التالية. لم تكن الحرب نزاعاً حدودياً فقط، بل مواجهة بين إمبراطورية مركزية ومدن ذات حكم ذاتي، وقد غذّت الهوية اليونانية المشتركة ورواية الحرية ضد الاستبداد. بقيت هذه الحروب مادة أساسية للتاريخ والفن والسياسة، ومثالاً على كيف تصنع رواية الانتصار ذاكرة أمة.", region:"europe", theme:"war", entity:"gr"},
    {year:-450, label:"450 ق.م", title:"قوانين الألواح الاثني عشر", body:"نحو 450 ق.م دوّن الرومان قوانينهم الأساسية على ألواح برونزية عُرضت في الساحة العامة، بعد مطالبات شعبية بأن تكون القواعد معلومة لا محتكرة لدى الكهنة والقضاة. نظّمت الألواح المحاكم والدين والديون والملكية والعلاقات الأسرية، ووضعت حداً لبعض التعسف القضائي. لم تكن القوانين عادلة بمعايير اليوم، لكن كتابتها وعلنها أسّست مبدأ سيادة القانون على السلطة الشخصية، وظلت أساساً للفكر القانوني الروماني والأوروبي.", region:"europe", theme:"rights", entity:"it"},
    {year:-400, label:"400 ق.م", title:"لاو تسي والفكر الطاوي", body:"نحو 400 ق.م تُنسب إلى لاو تسي نصوص الطاوية الأولى، التي تدعو إلى الانسجام مع الطبيعة والابتعاد عن التدخل الزائد والسلطة الثقيلة، وتستخدم المفارقة والصمت أسلوباً معرفياً. لم تكن الطاوية ديناً شعبياً في بدايتها، بل فلسفة عن الحكم والذات والكون، ثم تطوّرت إلى ممارسات دينية وطبية. وازنت بذلك الكونفوشية العملية، فصار الفكر الصيني مزيجاً بين تنظيم اجتماعي صارم وتصور أكثر مرونة للعلاقة بين الإنسان والكون.", region:"asia", theme:"religion", entity:"cn"},
    {year:-336, label:"336 ق.م", title:"الإسكندر الأكبر والفتح الهلنستي", body:"في 336 ق.م تولى الإسكندر العرش المقدوني، ثم قاد في نحو عشر سنوات حملة وصلت من مصر إلى وادي السند، فأسقط الإمبراطورية الأخمينية وأسس مدناً وخلط شعوباً وثقافات. لم تدم إمبراطوريته بعد موته، لكن ما أنتجه من عالم هلنستي مشترك بقي قروناً: لغة يونانية إدارية، وفنون مختلطة، وتجارة ونقل علمي بين المتوسط وآسيا. يُقرأ الإسكندر اليوم كحالة عن قدرة الفرد على تحويل الخريطة، وعن حدود المشروع الذي لا يقوم على مؤسسات دائمة.", region:"europe", theme:"war", entity:"gr"},
    {year:-321, label:"321 ق.م", title:"الإمبراطورية الماورية في الهند", body:"في 321 ق.م أسس تشاندراغوبتا الماوري دولة في شمال الهند بعد إسقاط سلالة ناندا، ووسّعها حتى البنغال وأفغانستان، ثم دخل في مواجهة مع السلوقيين. اعتمدت الدولة على جيش كبير وجباية منظمة وتجارة ومدن مزدهرة، وترك أحد وزرائها نصاً في فن الحكم والاقتصاد. مثّلت الماورية أول وحدة سياسية كبرى في شبه القارة، ومهّدت لنشر البوذية خارج الهند عبر بعثات تجارية ودينية.", region:"asia", theme:"politics", entity:"in"},
    {year:-300, label:"300 ق.م", title:"مكتبة الإسكندرية", body:"نحو 300 ق.م بدأ بطلميوس الأول بناء مكتبة ومؤسسة بحثية في الإسكندرية، جمعت نصوصاً يونانية وفارسية ومصرية، وعمل فيها علماء في الفلك والطب والجغرافيا والرياضيات. لم تكن المكتبة مجرد مخزن، بل مشروع لتراكم المعرفة وتصنيفها ونقدها، وأسهمت في قياس محيط الأرض وتقدّم التشريح. أثارت فكرة المكتبة الشاملة جدلاً قديماً وحديثاً، ويبقى اندثارها رمزاً لهشاشة المعرفة أمام الصراع السياسي والانحلال المؤسسي.", region:"africa", theme:"knowledge", entity:"eg"},
    {year:-260, label:"260 ق.م", title:"أشوكا والبذور السياسية للبوذية", body:"بعد حرب كالينغا الدامية نحو 260 ق.م تبنّى الملك أشوكا لغة أخلاقية في الحكم، تُعرف بالدارما، ونقش مبادئها على صخور وأعمدة في أنحاء الهند، وأرسل بعثات دينية إلى سريلانكا وآسيا الوسطى. لم يتحول أشوكا إلى راهب، لكنه ربط السياسة بالمسؤولية الأخلاقية تجاه البشر والحيوان، وأسّس تقليداً في الإعلان العام للقيم. بفضل رعايته انتقلت البوذية من حركة محلية إلى دين عالمي عبر طرق التجارة.", region:"asia", theme:"religion", entity:"in"},
    {year:-221, label:"221 ق.م", title:"تشين يوحّد الصين", body:"في 221 ق.م أكمل ملك تشين الفتوحات ووحّد الممالك المتحاربة في إمبراطورية واحدة، فوحّد الكتابة والأوزان والعملة والمقاييس، وأقام نظام مقاطعات يديره موظفون معيّنون لا وراثيون. مثّل هذا التوحيد قطيعة مع نظام الأسر الإقطاعية، وأسّس نموذج الدولة البيروقراطية المركزية الذي بقي مرجعاً للصين ألفي سنة. رغم قسوة النظام وسرعة انهياره، فإن أدواته الإدارية انتقلت إلى أسرة هان ورسّخت فكرة الوحدة كقيمة سياسية عليا.", region:"asia", theme:"politics", entity:"cn"},
    {year:-200, label:"200 ق.م", title:"هان وتوسيع سور الصين", body:"في مطلع القرن الثاني قبل الميلاد عزّزت أسرة هان حدودها الشمالية بسدود وأسوار ترابية رُبطت لاحقاً بما عُرف بسور الصين العظيم، وواجهت اتحاد قبائل شيونغنو في السهوب. لم يكن السور جداراً واحداً، بل شبكة دفاع ومراقبة وطرق إمداد ونقاط تجارة، عكست صراعاً طويلاً بين اقتصاد زراعي واقتصاد رعوي. أثّرت هذه المواجهة في تشكيل الدولة الصينية وتوسعها غرباً، وفي نشوء طرق التجارة التي ربطت الصين بآسيا الوسطى.", region:"asia", theme:"war", entity:"cn"},
    {year:-146, label:"146 ق.م", title:"تدمير قرطاج وقيام الهيمنة الرومانية", body:"في 146 ق.م أنهت روما الحرب البونيقية الثالثة بتدمير قرطاج وبيع أهلها، بعد سنوات من الصراع بدأ بهانيبال في 218 ق.م. لم تكن النتيجة مجرد سقوط مدينة، بل انتقال مركز الثقل في غرب المتوسط إلى روما، وتحوّل الجمهورية إلى قوة بحرية وإمبراطورية. في العام نفسه أخضعت روما اليونان، فتدفّقت الثقافة الهلنستية إلى إيطاليا. هكذا مهّدت هذه الحرب لنموذج إمبراطوري روماني جمع القوة العسكرية بالاستيعاب الثقافي.", region:"europe", theme:"war", entity:"it"},
    {year:-130, label:"130 ق.م", title:"طريق الحرير يفتح آسيا للتبادل", body:"نحو 130 ق.م عاد المبعوث الصيني تشانغ تشيان من رحلاته إلى آسيا الوسطى بمعلومات عن ممالك بعيدة ومنتجات وطرق، فبدأت الصين علاقات تجارية ودبلوماسية عبر ما عُرف لاحقاً بطريق الحرير. لم يكن طريقاً واحداً، بل شبكة برية وبحرية نقلت الحرير والخيول والتوابل، ومعها البوذية والفنون والتقنيات والأوبئة. أهميته أنه جعل آسيا وأوروبا والشرق الأوسط فضاء تبادل متصلاً، وأثبت أن التجارة أسرع وسيلة لنقل الأفكار.", region:"asia", theme:"economy", entity:"cn"},
    {year:-100, label:"100 ق.م", title:"تيوتيهواكان: مدينة الأهرامات", body:"نحو 100 ق.م بدأت تيوتيهواكان في وادي المكسيك بالنمو إلى مدينة ضخمة، بهرمي الشمس والقمر وشارع للموتى وأحياء سكنية متعددة الأعراق، بلغ سكانها لاحقاً عشرات الآلاف. قامت على الزراعة المروية والزراعة المكثفة وموقع وسيط في تجارة السبج والريش. أثّرت فنونها ومعتقداتها في معظم أمريكا الوسطى، ثم انهارت لأسباب داخلية وبيئية قبل صعود الأزتك، فبقيت آثارها مصدر شرعية لمن جاء بعدها.", region:"americas", theme:"culture", entity:"mx"},
    {year:-58, label:"58 ق.م", title:"قيصر وحروب الغال", body:"من 58 ق.م قاد يوليوس قيصر حملات في الغال امتدت سنوات، ضمّت أراضي فرنسا وبلجيكا وجزءاً من بريطانيا إلى روما، ووصفها بنفسه في كتابه عن الحرب الغالية. لم تكن الحملة مجرد توسع عسكري، بل أعادت تشكيل هوية الغال ومدنه وقبائله، وأدخلت اللاتينية والمدن الرومانية إلى قلب أوروبا الغربية. كما منحت قيصر جيشاً وفيّاً وثروة وشهرة مكّنته من تجاوز الجمهورية، فساهم فتحه في انهيارها لاحقاً.", region:"europe", theme:"war", entity:"fr"},
    {year:-27, label:"27 ق.م", title:"أغسطس وقيام الإمبراطورية الرومانية", body:"في 27 ق.م منح مجلس الشيوخ أوكتافيوس لقب أغسطس، فبدأ نظام إمارة يحتفظ فيه بمظاهر الجمهورية مع سلطة فعلية مركزة على الجيش والمال والولايات. أنهى هذا الترتيب قرناً من الحروب الأهلية، وأطلق فترة سلام داخلي نسبي وازدهار عمراني وتشريعي. نجح أغسطس في إخفاء الملكية داخل مؤسسات قديمة، فأنتج نموذجاً للحكم دام قروناً، وأثبت أن الشرعية قد تُبنى على الشكل بقدر ما تُبنى على القوة.", region:"europe", theme:"politics", entity:"it"},
    {year:-4, label:"4 ق.م", title:"ميلاد المسيحية في فلسطين", body:"نحو 4 ق.م وُلد يسوع في فلسطين الواقعة تحت الحكم الروماني، وفيها بدأ بعد نحو ثلاثين سنة دعوة دينية تدعو إلى محبة القريب والتوبة ومملكة إلهية غير أرضية. لم تكن حركة كبيرة في حياته، لكن تلاميذه نشروا تعاليمه في المدن اليونانية، فتحولت إلى دين منفصل عن اليهودية وانتشر في الإمبراطورية. صار المسيح مركز حضارة كاملة في أوروبا والعالم، ومصدر تشريع وفن وفكر ونزاعات دامت قروناً.", region:"middle-east", theme:"religion", entity:null},
    {year:70, label:"70", title:"تدمير الهيكل الثاني في القدس", body:"في 70 م اقتحمت جيوش روما بقيادة تيطس القدس وأحرقت الهيكل الثاني، بعد ثورة يهودية كبرى بدأت قبل ذلك بأربع سنوات، ودُمّرت المدينة جزئياً ونُقل كثير من أهلها. لم يكن الحدث نهاية اليهودية، بل حوّل مركزها من الهيكل والكهنوت إلى التوراة والمدارس والشتات. كما شكّل نقطة تحوّل في تشكّل المسيحية المبكرة، التي فصلت نفسها تدريجياً عن المجتمع اليهودي، ورسّخ الحدث في الذاكرة الدينية والسياسية للمنطقة.", region:"middle-east", theme:"religion", entity:null},
    {year:105, label:"105", title:"تطوير الورق في الصين", body:"في 105 م نُسب إلى المسؤول الصيني تساي لون تطوير طريقة لصناعة الورق من ألياف نباتية وخرق، فأنتج مادة أخف وأرخص من الحرير والخيزران المستخدمين للكتابة. انتشرت الصناعة تدريجياً في آسيا ثم وصلت إلى العالم الإسلامي في القرن الثامن، ومنه إلى أوروبا. لم يكن الورق اختراعاً واحداً بل سلسلة تحسينات، لكنه غيّر شروط المعرفة: أرخص الكتب، وسّع المدارس والدواوين، ومهّد للطباعة ثم للقراءة الجماهيرية.", region:"asia", theme:"technology", entity:"cn"},
    {year:127, label:"127", title:"الكوشان ونقل البوذية إلى آسيا الوسطى", body:"في القرن الثاني الميلادي بلغت الإمبراطورية الكوشانية ذروتها في أفغانستان وشمال الهند، وربطت بين طرق التجارة والثقافات تحت حكم كانيشكا. شجّع البلاط البوذية، وظهر في هذه البيئة فن نحت بشري للمسيح بوذا بدل الرموز المجردة، ثم انتقل هذا النمط إلى الصين وآسيا الوسطى. أهمية الكوشان أنها صنعت الجسر الذي عبرت عليه البوذية من الهند إلى شرق آسيا، ومعه أنماط فنية ولغات وكتابات جديدة.", region:"asia", theme:"religion", entity:null},
    {year:200, label:"200", title:"ثقافة هوبويل وتلال أمريكا الشمالية", body:"بين نحو 200 و500 م ازدهرت في شرق أمريكا الشمالية ثقافة هوبويل، التي بنت تلالاً ترابية هندسية ضخمة وشبكات تجارة امتدت من البحيرات الكبرى إلى خليج المكسيك. اعتمدت على الزراعة والجمع وصناعة الأدوات من السبج والنحاس والصدف، وعلى طقوس دفن تعكس تفاوتاً اجتماعياً. تدل هذه التلال على تنظيم جماعي ومعتقدات مشتركة بلا دولة مركزية، وتذكّر بأن أمريكا الشمالية كانت مسرحاً لحضارات معقدة قبل الاتصال الأوروبي بقرون.", region:"americas", theme:"culture", entity:null},
    {year:224, label:"224", title:"قيام الإمبراطورية الساسانية", body:"في 224 م أسقط أردشير الأول الأسرة الفرثية وأسس الإمبراطورية الساسانية، فصارت فارس قوة مركزية تجمع بين سلطة الملك والزرادشتية الرسمية. نظّمت الدولة الضرائب والطرق والمدن، وواجهت روما ثم بيزنطة في حروب طويلة، وتبنّت هوية إيرانية متميزة. امتد نفوذها إلى الخليج وآسيا الوسطى، ولعبت دوراً حاسماً في نقل الإدارة والعلوم إلى العالم الإسلامي بعد سقوطها في القرن السابع، فبقيت آثارها في المؤسسات واللغة والفن.", region:"middle-east", theme:"politics", entity:"ir"},
    {year:250, label:"250", title:"أكسوم واقتصاد البحر الأحمر", body:"في القرن الثالث الميلادي صعدت مملكة أكسوم في الهضبة الإثيوبية، وسيطرت على ميناء أدوليس وطرق البحر الأحمر والتجارة مع الهند والرومان، وسكّت عملاتها الخاصة. اعتمدت على الزراعة والمرتفعات والذهب والعاج، وتبنّت المسيحية في القرن الرابع، فصارت مركزاً دينياً وتجارياً مستقلاً. تُظهر أكسوم أن أفريقيا الشرقية كانت طرفاً فاعلاً في اقتصاد المحيط الهندي، لا هامشاً معزولاً، وأن الدول الأفريقية صنعت شبكاتها الخاصة.", region:"africa", theme:"economy", entity:"et"},
    {year:250, label:"250", title:"بداية العصر الكلاسيكي للمايا", body:"نحو 250 م دخلت حضارة المايا عصرها الكلاسيكي، حيث قامت مدن مثل تيكال وكالاكمول وبالينكي بهرمات ومعابد وكتابات هيروغليفية ونظم فلكية دقيقة. لم تكن المايا دولة واحدة، بل شبكة مدن متنافسة تتبادل وتتحارب، مع نخبة كهنوتية وملكية وسجلات تاريخية. أنتجت هذه الفترة تقويماً دقيقاً ورياضيات متقدمة وفنوناً غنية، وتُعد شاهداً على أن التعقيد الحضري لا يتطلب نهراً واحداً ولا إمبراطورية موحدة.", region:"americas", theme:"culture", entity:"mx"},
    {year:250, label:"250", title:"أزمة القرن الثالث في الإمبراطوريتين", body:"بين 235 و284 م مرّت الإمبراطورية الرومانية بأزمة حادة: اغتيال أباطرة وتفكك حدودي وتضخم وانحسار تجارة، في وقت كانت فيه الإمبراطورية الساسانية تتوسع وتضغط على الشرق. أدت الأزمة إلى إصلاحات دقلديانوس التي عزّزت المركزية والجباية والجيش، وإلى تحوّل تدريجي نحو نظام أكثر بيروقراطية. تُقرأ الأزمة كنموذج لكيف يمكن لضغوط متزامنة، عسكرية واقتصادية ووبائية، أن تعيد تشكيل دولة عظمى من الداخل قبل أن تنقسم.", region:"global", theme:"politics", entity:null},
    {year:313, label:"313", title:"مرسوم ميلانو والتسامح مع المسيحية", body:"في 313 م أصدر قسطنطين وليكينيوس مرسوماً في ميلانو يمنح المسيحيين حرية العبادة ويعيد ممتلكاتهم، بعد عقود من الاضطهاد. لم يكن المرسوم تحويلاً شخصياً بقدر ما كان قراراً سياسياً لإخماد نزاع ديني يقسّم الإمبراطورية، لكنه غيّر مسار التاريخ: صارت المسيحية ديناً مسموحاً ثم مفضلاً ثم رسمياً. من هذا التحول نشأت مؤسسات الكنيسة والقانون الكنسي والتعليم الغربي، وعلاقة معقدة بين السلطة الدينية والسياسية في أوروبا.", region:"europe", theme:"religion", entity:"it"},
    {year:330, label:"330", title:"القسطنطينية عاصمة جديدة", body:"في 330 م دشّن قسطنطين مدينة على موقع بيزنطة باسم القسطنطينية، لتكون عاصمة قريبة من حدود الدانوب والفرات وأكثر أماناً من روما. جمعت المدينة بين مؤسسات رومانية وفنون يونانية ومسيحية، ونمت بسرعة بفضل موقعها التجاري وأسواقها وتحصيناتها. بقيت عاصمة الإمبراطورية الشرقية ألف سنة، ومركزاً للعالم الأرثوذكسي، ومحطة رئيسية في طرق التجارة بين أوروبا وآسيا، قبل أن تتحول إلى إسطنبول العثمانية.", region:"europe", theme:"politics", entity:"tr"},
    {year:427, label:"427", title:"نالاندا: أول جامعة كبيرة", body:"نحو 427 م تأسس دير نالاندا في شمال الهند، وتحوّل إلى مؤسسة تعليمية كبرى تستقبل طلاباً من الصين وآسيا الوسطى وجنوب شرق آسيا، وتدرّس البوذية والفلسفة والطب والمنطق واللغة. لم تكن نالاندا جامعة بالمعنى الحديث، لكنها طوّرت سكناً جماعياً ومناهج ومناقشات وحفظ نصوص ونسخها. استمرت قروناً حتى دُمّرت في القرن الثاني عشر، وتركت أثراً في تنظيم التعليم في آسيا، وفي صورة الهند كمركز معرفي عالمي.", region:"asia", theme:"knowledge", entity:"in"},
    {year:476, label:"476", title:"سقوط الإمبراطورية الرومانية الغربية", body:"في 476 م خلع القائد الجرماني أودواكر الإمبراطور الروماني الغربي رومولوس أوغستولوس، ولم يعيّن خلفاً له، وهو ما يُعد تقليدياً نهاية الإمبراطورية الغربية. لم يكن الحدث انقطاعاً مفاجئاً، بل نتيجة عقود من الضعف المالي والعسكري وتوطين الشعوب الجرمانية داخل الحدود. قامت في الغرب ممالك جديدة جمعت التقاليد الرومانية بالقوانين الجرمانية، وبدأ ما يُعرف بالعصور الوسطى، بينما بقي الشرق بيزنطياً قروناً أخرى.", region:"europe", theme:"politics", entity:"it"},
    {year:534, label:"534", title:"قانون جستنيان وتدوين القانون الروماني", body:"في 534 م صدرت الطبعة النهائية من مجموعة القوانين التي أمر بها الإمبراطور البيزنطي جستنيان، فجمعت تشريعات روما القديمة وآراء الفقهاء في نص منظم. لم تكن المجموعة مجرد أرشيف، بل أداة لتوحيد إمبراطورية متعددة الأعراق، وأساس لتعليم القانون في بيزنطة ثم في أوروبا. أعاد الأوروبيون اكتشافها في العصور الوسطى، فصارت أساس القانون المدني في كثير من الدول، ودليلاً على أن النص القانوني يمكن أن يعيش أطول من الدولة التي أنتجته.", region:"europe", theme:"rights", entity:"by"},
    {year:541, label:"541", title:"طاعون جستنيان", body:"في 541 م ظهر وباء في مصر ثم انتقل إلى القسطنطينية وسواحل المتوسط، وأودى بحياة أعداد كبيرة من السكان في مدن الإمبراطورية البيزنطية وما حولها. لم تكن الإصابة واحدة، بل موجات متكررة أضعفت الجيوش والجباية والزراعة، وأسهمت في تراجع القدرة البيزنطية على التوسع. تُقرأ الحادثة اليوم ضمن تاريخ الأوبئة العالمية، إذ تبيّن كيف يمكن لعامل بيولوجي صغير أن يغيّر ميزان القوى والاقتصاد بسرعة أكبر من الحروب.", region:"global", theme:"environment", entity:null},
    {year:610, label:"610", title:"بداية الوحي ونشأة الإسلام", body:"نحو 610 م بدأ محمد بن عبد الله، تاجر من قريش في مكة، يدعو إلى عبادة إله واحد والعدل والصدق والزهد في الأصنام، في مجتمع قبلي يقوم على التجارة والحلف. لاقت الدعوة مقاومة من نخبة مكة، فوجدت ملاذاً في يثرب ثم انتشرت في الجزيرة العربية. لم يكن الإسلام حركة دينية فقط، بل أنتج لاحقاً نظاماً قانونياً وسياسياً وثقافياً واسعاً، وأعاد تشكيل الشرق الأوسط وشمال أفريقيا وآسيا الوسطى في قرون قليلة.", region:"middle-east", theme:"religion", entity:"sa"},
    {year:622, label:"622", title:"الهجرة وقيام أول مجتمع إسلامي", body:"في 622 م انتقل النبي محمد وأصحابه من مكة إلى يثرب، التي صارت المدينة، وأسسوا فيها مجتمعاً سياسياً يقوم على عقد بين المهاجرين والأنصار وقبائل المدينة. شكّل هذا العقد أساساً لتنظيم العلاقات بين الجماعات الدينية والقبائل، وربط السلطة بالتشريع لا بالنسب وحده. اتُّخذت الهجرة بداية للتقويم الإسلامي، لأنها لحظة تحوّل من دعوة مضطهدة إلى جماعة منظمة قادرة على بناء دولة.", region:"middle-east", theme:"religion", entity:"sa"},
    {year:632, label:"632", title:"الخلافة الراشدة وبداية الفتوحات", body:"بعد وفاة النبي محمد في 632 م تولى أبو بكر الخلافة، فوحّد الجزيرة العربية بعد حروب الردة، ثم بدأت الفتوحات نحو الشام والعراق ومصر. قامت الخلافة على بيعة وشورى محدودة وجيش منظم وديوان للعطاء، وسمحت للشعوب المفتوحة بالاحتفاظ بأديانها مقابل الجزية. أنتج هذا النموذج إمبراطورية سريعة الاتساع، وأثار في الوقت نفسه نقاشاً دائماً حول شرعية السلطة وحدود المشاركة السياسية في الإسلام.", region:"middle-east", theme:"politics", entity:"sa"},
    {year:711, label:"711", title:"فتح الأندلس", body:"في 711 م عبر طارق بن زياد إلى شبه الجزيرة الإيبيرية بجيش من البربر والعرب، فأسقط مملكة القوط الغربيين في معركة وادي لكة، وبدأ حكم إسلامي دام قروناً. لم يكن الوجود الإسلامي احتلالاً عسكرياً فقط، بل أنتج مدناً ومزارع وبساتين ومدارس وترجمات، وتعايشاً وصراعاً بين مسلمين ومسيحيين ويهود. صارت الأندلس جسراً انتقلت عبره الفلسفة والعلوم العربية إلى أوروبا، وأحد أعظم أمثلة التلاقي الثقافي في التاريخ.", region:"europe", theme:"war", entity:"es"},
    {year:732, label:"732", title:"معركة بلاط الشهداء", body:"في 732 م أوقفت قوات الفرنجة بقيادة شارل مارتل تقدّماً إسلامياً قرب بواتييه في فرنسا، في معركة عُرفت في المصادر العربية ببلاط الشهداء. لم تكن المعركة نهاية خطر حقيقي على أوروبا كما تُصوّر أحياناً، لكنها ثبّتت حدود التوسع شمالاً، وعزّزت مكانة الفرنجة في الغرب. أهميتها الحقيقية أنها ساعدت في تشكيل سلالة كارولنجية صعدت لاحقاً إلى الحكم، فربطت بين حدث عسكري ومسار بناء الدولة الأوروبية.", region:"europe", theme:"war", entity:"fr"},
    {year:750, label:"750", title:"الثورة العباسية", body:"في 750 م أسقطت حركة العباسيين الدولة الأموية بعد صراع بدأ في خراسان واستند إلى شبكات دعوة وشعوب غير عربية وشعور بالتهميش. نقلت الثورة مركز الخلافة من دمشق إلى العراق، وفتحت المجال لمشاركة أوسع في الإدارة والجيش والعلم. لم تكن مجرد تغيير سلالة، بل تحوّل في طبيعة الدولة الإسلامية من إمبراطورية عربية إلى كيان متعدد الثقافات، وهو ما تجلّى لاحقاً في بغداد ونهضتها العلمية.", region:"middle-east", theme:"politics", entity:"iq"},
    {year:762, label:"762", title:"بناء بغداد", body:"في 762 م أسس الخليفة المنصور مدينة بغداد قرب دجلة، بتخطيط دائري وقصر ومسجد وأسواق وأحياء حرفية، لتصبح عاصمة العباسيين ومركزاً إدارياً وتجارياً. جذب موقعها التجار والصناع والعلماء من فارس والهند والصين وبيزنطة، فتحولت في قرن إلى أكبر مدن العالم تقريباً. صارت بغداد رمزاً لمدينة عالمية تجمع المال والمعرفة والتنوع، ومهداً لحركة ترجمة وعلم أسهمت في تشكيل الحضارة الإسلامية الكلاسيكية.", region:"middle-east", theme:"knowledge", entity:"iq"},
    {year:793, label:"793", title:"غزو ليندسفارن وبداية عصر الفايكنغ", body:"في 793 م هاجم بحارة من اسكندنافيا دير ليندسفارن على ساحل إنكلترا، في حادثة تُعد بداية عصر الفايكنغ في أوروبا. لم تكن الهجمات مجرد نهب، بل جزء من توسع تجاري وسكاني واسع امتد من بحر الشمال إلى روسيا والبحر المتوسط وشمال الأطلسي. أسس الفايكنغ مدناً وطرق تجارة وحكماً في مناطق عدة، وأثّرت غاراتهم في تنظيم الدفاع الأوروبي وفي تشكّل ممالك إنكلترا وفرنسا وروسيا.", region:"europe", theme:"war", entity:"gb"},
    {year:800, label:"800", title:"تتويج شارلمان وإمبراطورية الغرب", body:"في 800 م تُوّج شارلمان إمبراطوراً في روما، بعد أن وحّد معظم أوروبا الغربية بالحرب والتحالفات والإدارة، وأقام شبكة كونتات ومدارس كاتدرائية وإصلاحاً للكتابة. لم تكن إمبراطوريته استعادة لروما، بل كياناً فرنجياً مسيحياً جديداً جمع السلطة العسكرية برعاية الكنيسة. أنشأ التتويج سابقة في الشرعية الأوروبية، وأثار توتراً مع بيزنطة، ومهّد لفكرة الإمبراطورية الرومانية المقدسة التي استمرت قروناً.", region:"europe", theme:"politics", entity:"fr"},
    {year:868, label:"868", title:"أقدم كتاب مطبوع معروف", body:"في 868 م طُبع في الصين نص بوذي يُعرف بسوترا الماس، ويُعد من أقدم الكتب المطبوعة المؤرخة التي وصلتنا، باستخدام ألواح خشبية محفورة. سبقت هذه التقنية الطباعة الأوروبية بقرون، واعتمدت على الورق والحبر والحفر اليدوي، فجعلت نسخ النصوص أسرع وأرخص. انتشرت الطباعة الخشبية في شرق آسيا، ونقلت الأدب والدين والمعارف العملية، وأثبتت أن ثورة المعرفة لا تحتاج دائماً إلى آلة معقدة بل إلى تنظيم وحرفة.", region:"asia", theme:"technology", entity:"cn"},
    {year:900, label:"900", title:"انهيار مدن المايا الكلاسيكية", body:"بين القرنين الثامن والعاشر تراجعت مدن المايا الجنوبية الكبرى وهُجرت معابدها تدريجياً، في تحوّل يُعرف بانهيار الفترة الكلاسيكية. يرجّح الباحثون تداخل الجفاف وتدهور التربة وزيادة الحروب وضعف الشرعية الملكية، بدل سبب واحد. لم تنته المايا، بل انتقل مركز ثقلها إلى الشمال واليوكاتان حيث ازدهرت مدن جديدة. يعرض هذا الانهيار درساً في هشاشة المدن المعتمدة على بيئة محدودة ونخبة ضيقة، حتى في حضارات تبدو في أوجها.", region:"americas", theme:"environment", entity:"mx"},
    {year:960, label:"960", title:"قيام أسرة سونغ", body:"في 960 م أسس تشاو كوانغين أسرة سونغ، فبدأت مرحلة من الازدهار الاقتصادي والتقني غير مسبوق في الصين، مع مدن كبيرة وأسواق نشطة وعملة ورقية وطباعة وبوصلة وبارود. طوّرت الدولة نظام امتحانات لاختيار الموظفين، فقلّدت مكانة النبلاء الوراثيين بطبقة إدارية متعلّمة. رغم ضعفها العسكري أمام شعوب الشمال، أنتجت سونغ تحولاً تجارياً وثقافياً جعل الصين أكبر اقتصاد في العالم في ذلك الوقت.", region:"asia", theme:"politics", entity:"cn"},
    {year:1054, label:"1054", title:"الانقسام الكبير بين روما والقسطنطينية", body:"في 1054 م تبادل مندوبو البابا وبطريرك القسطنطينية الحرمان، في ذروة خلافات حول السلطة واللاهوت والطقوس، فانقسمت المسيحية إلى كنيسة غربية وأخرى شرقية. لم يكن الانقسام حدثاً واحداً، بل نتيجة تراكم قرون من الاختلاف اللغوي والسياسي والثقافي. رسّخ الانفصال هويتين حضاريتين، وأثر في الحروب والتحالفات والاستشراق، وظلّ حاجزاً في العلاقات بين أوروبا الغربية والشرقية حتى محاولات المصالحة الحديثة.", region:"europe", theme:"religion", entity:null},
    {year:1066, label:"1066", title:"معركة هاستينغز والغزو النورماندي", body:"في 1066 م انتصر وليام دوق نورماندي على هارولد الثاني في هاستينغز، فبدأ غزو إنكلترا الذي أعاد تشكيل نخبتها ولغتها وقانونها. أدخل النورمان نظاماً إقطاعياً مركزياً وسجلات للأراضي وقلاعاً حجرية، ومزج الفرنسية بالإنجليزية، فأنتج لغة وثقافة هجينة. ربط الغزو إنكلترا بأوروبا القارية، وجعلها طرفاً في صراعاتها، وأسّس لسياسة خارجية بحرية استمرت قروناً في تشكيل التاريخ البريطاني.", region:"europe", theme:"politics", entity:"gb"},
    {year:1099, label:"1099", title:"الحملة الصليبية الأولى وسقوط القدس", body:"في 1099 م استولت جيوش الحملة الصليبية الأولى على القدس بعد حصار دامئ، وأقامت في الشام كيانات لاتينية مثل مملكة القدس وإمارة أنطاكية. جاءت الحملة استجابة لدعوة بابوية وضغط سياسي واقتصادي أوروبي، لكنها أنتجت صداماً طويلاً مع العالم الإسلامي. لم تحقق أهدافها على المدى البعيد، لكنها رسّخت صورة متبادلة بين الشرق والغرب، وأعادت تشكيل التجارة المتوسطية ونقل المعرفة والفنون.", region:"middle-east", theme:"war", entity:null},
    {year:1100, label:"1100", title:"مدينة زيمبابوي العظمى", body:"نحو 1100 م بدأت مدينة زيمبابوي العظمى في جنوب أفريقيا بالازدهار، بأسوار حجرية بلا ملاط وأبراج ومنصات، وامتدت شبكات تجارتها إلى الساحل الشرقي حيث وصلت إلى الصين والهند. قام اقتصادها على الذهب والعاج والمواشي والزراعة، وعلى موقع وسيط بين الداخل الأفريقي والمحيط الهندي. تدل آثارها على دولة منظمة ومهارة معمارية عالية، وتفنّد الافتراضات القديمة التي أنكرت قدرة الأفارقة على بناء مدن كبرى بمواردهم.", region:"africa", theme:"economy", entity:null},
    {year:1150, label:"1150", title:"بناء أنغكور وات", body:"في منتصف القرن الثاني عشر بدأ الملك السوريافارمان الثاني بناء أنغكور وات في كمبوديا، معبداً ضخماً للإله فيشنو، ثم تحوّل لاحقاً إلى معبد بوذي. يعكس البناء قوة إمبراطورية الخمير ونظامها المائي القائم على الخزانات والقنوات التي سمحت بزراعة الأرز مرتين سنوياً. أهميته أنه يجمع بين الدين والملكية والهندسة وإدارة الماء في مشروع واحد، ويُظهر كيف بنت جنوب شرق آسيا دولاً كبرى بلا اتصال مباشر بالمتوسط.", region:"asia", theme:"culture", entity:null},
    {year:1187, label:"1187", title:"معركة حطين وصلاح الدين", body:"في 1187 م انتصر صلاح الدين الأيوبي على جيش مملكة القدس في حطين، ثم استعاد القدس ومعظم مدن الساحل، في تحوّل حاسم في موازين الصراع الصليبي. لم يكن الانتصار عسكرياً فقط، بل ثمرة توحيد مصر والشام وإصلاح الإدارة والجيش واستمالة القبائل. أعاد الحدث تشكيل الخريطة السياسية للمنطقة، وأطلق حملة صليبية ثالثة، ورسّخ صورة صلاح الدين في الذاكرة الإسلامية والأوروبية كرمز للوحدة والعدل في الحرب.", region:"middle-east", theme:"war", entity:null},
    {year:1206, label:"1206", title:"جنكيز خان وقيام الإمبراطورية المغولية", body:"في 1206 م وحّد تيموجين قبائل السهوب المنغولية واتخذ لقب جنكيز خان، ثم قاد حملات وصلت إلى الصين وبلاد فارس وروسيا، فأنشأ أكبر إمبراطورية متصلة في التاريخ. اعتمد الجيش المغولي على الفروسية والانضباط والمعلومات والحركة السريعة، وعلى سياسة رعب محسوبة لإخضاع المدن. رغم الدمار الواسع، أنتجت الإمبراطورية طرقاً آمنة وتبادلاً تجارياً وعلمياً بين الشرق والغرب، ونقلت تقنيات ومعارف وأوبئة عبر أوراسيا.", region:"asia", theme:"war", entity:null},
    {year:1215, label:"1215", title:"الماغنا كارتا", body:"في 1215 م أجبر نبلاء إنكلترا الملك جون على توقيع وثيقة عُرفت بالماغنا كارتا، تحدّ من جبايته التعسفية وتؤكد حقوقاً للنبلاء والكنيسة والمدن، وتمنع الاعتقال بلا إجراء قانوني. لم تكن الوثيقة ديمقراطية شاملة، لكنها أسّست مبدأ خضوع الملك للقانون، وأصبحت لاحقاً مرجعاً في الفكر الدستوري والحقوقي. أعيد إصدارها وتفسيرها مراراً، وساهمت في تطوّر البرلمان الإنجليزي وفي صياغة إعلانات الحقوق الحديثة.", region:"europe", theme:"rights", entity:"gb"},
    {year:1235, label:"1235", title:"إمبراطورية مالي وصعود سوندياتا", body:"نحو 1235 م وحّد سوندياتا كيتا ممالك غرب أفريقيا في إمبراطورية مالي بعد انتصاره على مملكة سوسو، فبدأ عصر ازدهار دام قرنين. قامت الإمبراطورية على الذهب والملح والتجارة عبر الصحراء، ومدن مثل تمبكتو وجني وجاو، وتحوّل ملوكها لاحقاً إلى الإسلام. أنتجت مالي نظام إدارة واسعاً وأسطولاً تجارياً ومراكز تعليم، وأثبتت أن غرب أفريقيا كان قلب اقتصاد عالمي قبل وصول الأوروبيين، لا هامشاً على خريطته.", region:"africa", theme:"politics", entity:"ml"},
    {year:1250, label:"1250", title:"استيطان الماوري في أوتياروا", body:"نحو 1250 م بدأ مستوطنون بولينيزيون بالوصول إلى نيوزيلندا في رحلات بحرية طويلة، فأسسوا مجتمع الماوري في جزر معزولة بمناخ بارد وموارد جديدة. طوّر هؤلاء زراعة الكومارا والصيد والنسيج والبناء الخشبي، وأنشأوا قبائل وعلاقات معقدة بالأرض والبحر. يمثّل استيطانهم آخر موجات التوسع البولينيزي الكبرى، ويُظهر قدرة الملاحة التقليدية على عبور مسافات شاسعة بلا أدوات حديثة، ويشكّل أساس الهوية الثقافية النيوزيلندية اليوم.", region:"oceania", theme:"exploration", entity:null},
    {year:1258, label:"1258", title:"سقوط بغداد", body:"في 1258 م اقتحمت جيوش هولاكو بغداد وأسقطت الخلافة العباسية، بعد حصار وتدمير واسع للمدينة ومكتباتها. لم يكن الحدث نهاية حضارة، لكنه أنهى رمزية الخلافة المركزية في العالم السني، وأضعف شبكات العلم التي كانت بغداد مركزها. انتقلت مراكز المعرفة إلى القاهرة ودمشق ومراكش وسمرقند، وتغيّر توازن القوى لصالح المماليك والمغول. ظلّ سقوط بغداد في الذاكرة الإسلامية علامة على هشاشة المدن أمام القوة العسكرية.", region:"middle-east", theme:"war", entity:"iq"},
    {year:1299, label:"1299", title:"قيام الدولة العثمانية", body:"نحو 1299 م بدأت إمارة عثمانية صغيرة في شمال غرب الأناضول بالتوسع على حساب بيزنطة، ثم تحوّلت إلى دولة عابرة للقارات. اعتمدت على مزيج من الفروسية والإنكشارية والإدارة المرنة واستيعاب النخب المحلية، وعلى موقع يربط البلقان بالشرق. استمرت ستة قرون، وحكمت أجزاء واسعة من أوروبا وآسيا وأفريقيا، وأنتجت نظاماً قانونياً وإدارياً مؤثراً، وظلت مرجعاً في النقاش حول الإرث السياسي للمنطقة.", region:"middle-east", theme:"politics", entity:"tr"},
    {year:1324, label:"1324", title:"حج منسا موسى وذهب مالي", body:"في 1324 م أدى منسا موسى، حاكم مالي، فريضة الحج إلى مكة في موكب ضخم، وتوزيع الذهب في القاهرة والشام بشكل أثّر في أسعار السوق لسنوات. لم تكن الرحلة استعراضاً فقط، بل دبلوماسية اقتصادية ربطت غرب أفريقيا بالعالم الإسلامي، وجذبت العلماء والتجار إلى تمبكتو وجني. تحوّلت مالي بعدها إلى مركز تعليمي بتأسيس مساجد ومدارس، وصارت صورة منسا موسى في المصادر الأوروبية أول انطباع واسع عن ثروة أفريقيا.", region:"africa", theme:"economy", entity:"ml"},
    {year:1325, label:"1325", title:"تأسيس تينوتشتيتلان", body:"نحو 1325 م أسس المكسيكا مدينة تينوتشتيتلان على جزيرة في بحيرة تيكسكوكو، بعد رحلات ترحال طويلة في وادي المكسيك. بنيت المدينة على جزر صناعية وقنوات وحدائق عائمة وأسواق واسعة، وربطت القبائل المحيطة بتحالفات وضرائب. تحوّلت في قرن إلى واحدة من أكبر مدن العالم، وأصبحت مركز إمبراطورية الأزتك التي جمعت بين الدين والحرب والتجارة، قبل أن يدمرها الغزو الإسباني في 1521.", region:"americas", theme:"politics", entity:"mx"},
    {year:1347, label:"1347", title:"الموت الأسود في أوروبا", body:"في 1347 م وصل الطاعون إلى موانئ المتوسط قادماً من آسيا عبر طرق التجارة، فانتشر في أوروبا خلال سنوات وأودى بحياة نسبة كبيرة من السكان. أدى النقص الحاد في اليد العاملة إلى ارتفاع الأجور وضعف نظام القنانة، وإلى أزمات شرعية وموجات من التطرف الديني والاضطهاد. لم يكن الوباء مجرد كارثة ديموغرافية، بل قوة أعادت تشكيل الاقتصاد والطبقات والعلاقة بين الإنسان والسلطة في نهاية العصور الوسطى.", region:"europe", theme:"environment", entity:null},
    {year:1368, label:"1368", title:"أسرة مينغ تعيد الحكم الصيني", body:"في 1368 م أطاحت انتفاضة فلاحية بقيادة تشو يوانتشانغ بأسرة يوان المغولية وأسست أسرة مينغ، التي أعادت المركزية الصينية ونقلت العاصمة إلى بكين. أعادت مينغ بناء القنوات والأسوار ونظام الامتحانات، ووسّعت الزراعة والتجارة، ثم أغلقت الحدود البحرية في فترات لاحقة. جمعت الدولة بين إحياء التقاليد وانفتاح بحري قصير، وشكّلت نموذجاً لدولة بيروقراطية قوية، قبل أن تضعف أمام ضغوط داخلية وصعود المانشو.", region:"asia", theme:"politics", entity:"cn"},
    {year:1405, label:"1405", title:"رحلات تشنغ خه", body:"من 1405 م قاد الأدميرال تشنغ خه أساطيل صينية ضخمة إلى جنوب شرق آسيا والهند والخليج والساحل الأفريقي، في سبع رحلات رسمية حملت الهدايا والتجارة والقوة البحرية. لم تكن الرحلات استيطانية، بل دبلوماسية إمبراطورية لإظهار الهيبة وجمع المعلومات والجزية الرمزية. توقفت بعد وفاة الإمبراطور، وتراجعت الصين عن التوسع البحري، بينما كان البرتغاليون يبدأون مسارهم. يثير هذا التوقف نقاشاً حول أسباب الانكفاء وأثره في ميزان القوى العالمي.", region:"asia", theme:"exploration", entity:"cn"},
    {year:1438, label:"1438", title:"باتشاكوتي وبناء إمبراطورية الإنكا", body:"في 1438 م تولى باتشاكوتي حكم كوسكو وبدأ توسعاً عسكرياً وإدارياً حوّل الإنكا من مملكة جبلية إلى إمبراطورية تمتد آلاف الكيلومترات على جبال الأنديز. اعتمدت الدولة على الطرق الحجرية والمخازن ونظام السخرة الدورية والسجلات المعقودة بالكيبو، وعلى إدارة محلية تحت سلطة مركزية. أنتجت الإنكا هندسة زراعية ومعمارية مذهلة بلا عجلة ولا كتابة أبجدية، وسقطت لاحقاً أمام الغزو الإسباني والحرب الأهلية والأوبئة.", region:"americas", theme:"politics", entity:null},
    {year:1440, label:"1440", title:"غوتنبرغ والطباعة بالحروف المتحركة", body:"نحو 1440 م بدأ يوهان غوتنبرغ في ماينتس تطوير طباعة بالحروف المعدنية المتحركة والزيت والحبر والورق، فأنتج نسخاً من الكتاب المقدس بسرعة لم تكن ممكنة للنسخ اليدوي. لم تكن التقنية جديدة تماماً، فقد عُرفت الطباعة الخشبية في آسيا، لكن الجمع بين الحروف القابلة لإعادة الاستخدام جعل النشر قابلاً للتوسع. انتشرت المطابع في أوروبا خلال عقود، فوسّعت القراءة والإصلاح الديني والثورة العلمية وتشكيل الرأي العام.", region:"europe", theme:"technology", entity:"de"},
    {year:1453, label:"1453", title:"سقوط القسطنطينية", body:"في 1453 م فتح السلطان محمد الثاني القسطنطينية بعد حصار استخدم فيه مدفعية ثقيلة، فانهت الدولة العثمانية الإمبراطورية البيزنطية بعد أكثر من ألف سنة. لم يكن السقوط نهاية عالم فقط، بل بداية ترتيب جديد للبحر المتوسط، حيث صارت إسطنبول عاصمة إمبراطورية عابرة للقارات. أثر الحدث في طرق التجارة الأوروبية ودوافع البحث عن طرق بديلة، وفي هجرة علماء بيزنطيين إلى إيطاليا، فعمّق التحول نحو عصر النهضة.", region:"europe", theme:"war", entity:"tr"},
    {year:1492, label:"1492", title:"رحلة كولومبوس والاتصال بالأمريكتين", body:"في 1492 م وصل كريستوفر كولومبوس، بحثاً عن طريق إلى آسيا، إلى جزر الكاريبي باسم إسبانيا، فبدأ اتصال دائم بين نصفي الكرة الأرضية لم يكن له مثيل. أطلق هذا الاتصال تبادلاً واسعاً للمحاصيل والحيوانات والأمراض، وأدى إلى غزو واستعمار وانهيار سكاني هائل في الأمريكتين، وإلى تدفق الفضة والذهب إلى أوروبا. يُعد الحدث نقطة تحول في التاريخ العالمي، لأنه أنشأ اقتصاداً متصلاً ونظاماً استعمارياً دام قروناً.", region:"americas", theme:"exploration", entity:"es"},
    {year:1501, label:"1501", title:"قيام الدولة الصفوية", body:"في 1501 م أسس إسماعيل الأول الدولة الصفوية في تبريز، وجعل التشيع الاثني عشري مذهب الدولة، فبدأ تحول ديني وسياسي عميق في إيران. وحّدت الدولة الولايات الفارسية وأقامت جيشاً وإدارة وطرقاً، وواجهت العثمانيين في صراعات طويلة حول الحدود والمشروعية. أنتجت الصفوية هوية إيرانية متميزة جمعت اللغة الفارسية والتشيع والفن المعماري، وأعادت رسم خريطة الشرق الأوسط الدينية التي ما تزال آثارها قائمة.", region:"middle-east", theme:"politics", entity:"ir"},
    {year:1517, label:"1517", title:"مارتن لوثر وبداية الإصلاح البروتستانتي", body:"في 1517 م نشر مارتن لوثر في فيتنبرغ اعتراضات على بيع صكوك الغفران، فتحوّلت شكوى لاهوتية إلى حركة إصلاح ديني وسياسي اجتاحت أوروبا. اعتمدت الحركة على الطباعة واللغات المحلية وحماية أمراء ألمان، ورفضت سلطة البابا في بعض المسائل، فانقسمت المسيحية الغربية. أدى الإصلاح إلى حروب دينية وإلى تشكيل هويات وطنية، وإلى تعليم شعبي أوسع، وأسّس لتعددية دينية لم تكن ممكنة قبل ذلك.", region:"europe", theme:"religion", entity:"de"},
    {year:1521, label:"1521", title:"سقوط تينوتشتيتلان", body:"في 1521 م سقطت تينوتشتيتلان بيد هرنان كورتيس وحلفائه من القبائل المعادية للأزتك، بعد حصار وأوبئة وصراع داخلي، فانهارت إمبراطورية الأزتك سريعاً. لم يكن الانتصار الإسباني ممكناً بلا التحالفات المحلية ولا بلا الجدري الذي فتّت السكان، وهي عوامل تُبرز هشاشة الإمبراطوريات القائمة على الإخضاع والجزية. أعاد السقوط تشكيل أمريكا الوسطى ديموغرافياً ولغوياً ودينياً، وأسّس نظاماً استعمارياً جمع بين السخرة والتبشير.", region:"americas", theme:"war", entity:"mx"},
    {year:1526, label:"1526", title:"معركة بانيبات وقيام الإمبراطورية المغولية", body:"في 1526 م انتصر ظهير الدين بابر في بانيبات على سلطنة دلهي، فأسس إمبراطورية المغول في الهند التي بلغت ذروتها لاحقاً في عهد أكبار. اعتمدت على المدفعية والفروسية وعلى دمج النخب المحلية في الإدارة والجيش، وطوّرت نظاماً ضريبياً ومناصب ومصاهرات. أنتجت الدولة المغولية فنوناً ومعماراً مثل تاج محل، ونظاماً قانونياً متعدد الأديان، وشكّلت أحد أكبر الاقتصادات في العالم قبل صعود الاستعمار البريطاني.", region:"asia", theme:"politics", entity:"in"},
    {year:1533, label:"1533", title:"سقوط إمبراطورية الإنكا", body:"في 1533 م دخل فرانسيسكو بيزارو كوسكو بعد أسر أتاهوالبا وقتله، فانهارت سلطة الإنكا المركزية أمام الغزو والانقسام الداخلي والأوبئة. لم يكن السقوط بسبب تفوق تقني فقط، بل بسبب حرب أهلية بين أبناء ويسنا وبسبب التحالفات المحلية مع الغزاة. حلّ محل الإنكا نظام استعماري قائم على التعدين والسخرة والتبشير، وأدى انهيار السكان إلى فقدان معرفة زراعية وإدارية واسعة، ما يجعل الحادثة مثالاً على كلفة الاستعمار المعرفية.", region:"americas", theme:"war", entity:null},
    {year:1543, label:"1543", title:"كوبرنيكوس ومركزية الشمس", body:"في 1543 م نشر نيكولاس كوبرنيكوس كتابه عن دورات الأفلاك، مقترحاً أن الشمس في مركز الكون وأن الأرض تدور حولها، خلافاً للنموذج البطلمي السائد. لم يكن الكتاب مقبولاً فوراً، لكنه فتح باباً للنقد والمراقبة والحساب، ثم أكمل غاليليو وكبلر مساره. مثّل هذا التحول بداية الثورة العلمية الحديثة، لأنه فصل المعرفة عن السلطة الدينية المباشرة، وأسّس فكرة أن النموذج يمكن أن يُختبر ويُصحّح.", region:"europe", theme:"knowledge", entity:"pl"},
    {year:1550, label:"1550", title:"تجارة الرقيق عبر الأطلسي", body:"في القرن السادس عشر توسّعت تجارة الأفارقة المستعبدين عبر الأطلسي لتغذية مزارع السكر والتبغ في الأمريكتين، فصارت ركيزة للاقتصاد الاستعماري. اعتمدت على شبكات ساحلية أفريقية وأسواق وقلاع وموانئ، ونقلت ملايين البشر في ظروف قاتلة. لم تكن جريمة اقتصادية فقط، بل أنتجت تفاوتاً عرقياً ومؤسسات عنصرية، وأعادت تشكيل سكان الأمريكتين وثقافاتهم، وظلت آثارها في التركيبة الاجتماعية والاقتصادية حتى اليوم.", region:"africa", theme:"economy", entity:null},
    {year:1571, label:"1571", title:"غاليون مانيلا وربط آسيا بالأمريكتين", body:"في 1571 م أسست إسبانيا مانيلا مركزاً لتجارة الغاليون بين الفلبين والمكسيك، فربطت الصين بأمريكا عبر المحيط الهادئ للمرة الأولى بشكل منتظم. حملت السفن الحرير والخزف والتوابل شرقاً، والفضة الأمريكية غرباً، فغيّرت أسعار العملات في الصين والهند وأوروبا. أنشأت هذه الطريق أول اقتصاد عالمي فعلي، وأدخلت محاصيل أمريكية إلى آسيا، وأظهرت أن العولمة بدأت قبل الثورة الصناعية بقرون.", region:"global", theme:"economy", entity:null},
    {year:1588, label:"1588", title:"هزيمة الأرمادا الإسبانية", body:"في 1588 م أبحرت أرمادا إسبانية ضخمة لغزو إنكلترا، لكنها تكبدت خسائر كبيرة بسبب العواصف وتكتيكات السفن الإنجليزية الأسرع، فعادت منهكة. لم تكن الهزيمة نهاية إسبانيا، لكنها كسرت أسطورة تفوقها البحري، وفتحت المجال لصعود القوى البحرية الشمالية. ربطت الحادثة بين الدين والسياسة والتجارة، إذ كانت إنكلترا البروتستانتية تتحدى إسبانيا الكاثوليكية، ومهّدت لسيطرة بحرية أوروبية شمالية على التجارة الأطلسية.", region:"europe", theme:"war", entity:"es"},
    {year:1600, label:"1600", title:"شركة الهند الشرقية الإنجليزية", body:"في 1600 م منح الملكة إليزابيث الأولى شركة الهند الشرقية احتكاراً للتجارة مع الشرق، فبدأت الشركة كتجمع تجاري وانتهت كقوة عسكرية وإدارية تحكم أجزاء واسعة من الهند. اعتمدت على رأس المال المشترك والأساطيل والحصون والاتفاقات مع الحكام المحليين، ثم على الجيوش والضرائب. مثّلت نموذجاً للشركة الاستعمارية التي تتجاوز الدولة، وأسهمت في تشكيل الاقتصاد العالمي الحديث وفي نشوء الإمبراطورية البريطانية في آسيا.", region:"europe", theme:"economy", entity:"gb"},
    {year:1603, label:"1603", title:"شوغونية توكوغاوا وتوحيد اليابان", body:"في 1603 م نال توكوغاوا إيـياسو لقب الشوغون، فأنهى قرناً من الحروب الأهلية وأسس نظاماً وراثياً حكم اليابان أكثر من قرنين. اعتمد على تقسيم الولاءات ومراقبة الأمراء وتقييد السلاح وتنظيم القرى والمدن، وعلى سياسة انغلاق بحري شبه تام. أنتجت هذه الفترة سلاماً داخلياً وازدهاراً حرفياً وثقافة مدنية غنية، لكنها جمّدت التحديث العسكري، فانهار النظام سريعاً أمام الضغط الغربي في القرن التاسع عشر.", region:"asia", theme:"politics", entity:"jp"},
    {year:1618, label:"1618", title:"حرب الثلاثين سنة", body:"في 1618 م بدأت حرب الثلاثين سنة في أوروبا الوسطى بانتفاضة بروتستانتية في بوهيميا، ثم تحولت إلى صراع أوسع بين السلالات والقوى الدينية. دُمّرت مناطق واسعة، وتراجعت أعداد السكان في بعض الأقاليم بشكل حاد، وتغيّر ميزان القوى لصالح فرنسا والسويد. لم تكن الحرب دينية فقط، بل صراع على السيادة والهيمنة الإقليمية، وأنتجت معاهدة وستفاليا التي أسّست فكرة توازن القوى وسيادة الدول في أوروبا الحديثة.", region:"europe", theme:"war", entity:"de"},
    {year:1644, label:"1644", title:"المانشو يؤسسون أسرة تشينغ", body:"في 1644 م دخل المانشو بكين بعد انهيار أسرة مينغ أمام انتفاضات داخلية، وأسسوا أسرة تشينغ التي حكمت الصين حتى 1912. حافظوا على المؤسسات الصينية والامتحانات الإدارية، لكنهم أبقوا هوية عسكرية منفصلة، ووسّعوا الإمبراطورية إلى تايوان ومنغوليا والتبت وتركستان. بلغت الصين في عهدهم أقصى اتساع جغرافي وازدهار سكاني، ثم واجهت ضغوطاً أوروبية واضطرابات داخلية أنهت النظام الإمبراطوري.", region:"asia", theme:"politics", entity:"cn"},
    {year:1648, label:"1648", title:"صلح وستفاليا", body:"في 1648 م أنهت معاهدات وستفاليا حرب الثلاثين سنة وحرب الثمانين سنة، واعترفت بسيادة الدول على أراضيها وبحقوق الأقليات الدينية في بعض المناطق. لم تُنشئ نظاماً دولياً كاملاً، لكنها أرسّخت مبدأ عدم التدخل وسيادة الدولة، وصارت مرجعاً في القانون الدولي. أنهت هيمنة الإمبراطورية الرومانية المقدسة، وسمحت لفرنسا والسويد بالصعود، وأسّست لغة دبلوماسية جديدة تقوم على التوازن والمصالح بدل السلطة الدينية.", region:"europe", theme:"politics", entity:null},
    {year:1683, label:"1683", title:"حصار فيينا الثاني", body:"في 1683 م حاصر جيش عثماني بقيادة الصدر الأعظم قره مصطفى فيينا، لكن الحصار فشل بعد وصول قوات بولندية وإمبراطورية، فبدأ تراجع عثماني طويل في أوروبا. لم يكن الفشل بسبب ضعف الجيش فقط، بل بسبب مشكلات الإمداد والتنسيق والتحالفات الأوروبية المضادة. أعقب الحصار هجوم هابسبورغي واسع استعاد المجر، واتفاقيات كارلوفيتز لاحقاً، فغيّر ميزان القوى في شرق أوروبا وأعاد تعريف حدود الدولة العثمانية.", region:"middle-east", theme:"war", entity:"tr"},
    {year:1687, label:"1687", title:"نيوتن ومبادئ الفلسفة الطبيعية", body:"في 1687 م نشر إسحاق نيوتن كتابه المبادئ، وفيه صاغ قوانين الحركة والجذب العام، وأثبت أن حركة الأجسام الأرضية والأجرام السماوية تخضع لقوانين واحدة. لم يكن الكتاب مجرد معادلات، بل إعادة تعريف للطبيعة كنظام قابل للقياس والتنبؤ، وأساس للميكانيكا الكلاسيكية. أثّر في الفلك والهندسة والاقتصاد والفلسفة، وأصبح رمزاً للثورة العلمية التي جعلت المعرفة أداة تحكم في العالم المادي.", region:"europe", theme:"knowledge", entity:"gb"},
    {year:1760, label:"1760", title:"بداية الثورة الصناعية في بريطانيا", body:"نحو 1760 م بدأت في بريطانيا سلسلة تحولات في الطاقة والنسيج والتعدين والنقل، جمعت الفحم والحديد والبخار ورأس المال والعمالة، فغيّرت طريقة الإنتاج. لم تكن الثورة حدثاً واحداً بل عملية امتدت عقوداً، اعتمدت على التجارة الاستعمارية والأسواق والأيدي العاملة المتاحة. أنتجت مدناً صناعية وطبقة عاملة جديدة وتلوثاً ونمواً سكانياً، وأعادت تشكيل ميزان القوى العالمي لصالح أوروبا، وأسّست اقتصاداً قائماً على النمو المستمر.", region:"europe", theme:"technology", entity:"gb"},
    {year:1770, label:"1770", title:"جيمس كوك يصل إلى الساحل الأسترالي", body:"في 1770 م وصل جيمس كوك إلى الساحل الشرقي لأستراليا ورسم خرائط له باسم بريطانيا، بعد رحلات علمية عبر المحيط الهادئ. لم يكن الوصول اكتشافاً لأرض غير مأهولة، فقد كان السكان الأصليون يعيشون فيها منذ عشرات الآلاف من السنين، لكنه فتح الطريق للاستيطان الأوروبي والاستعمار. أدت الرحلات إلى تبادل معلومات جغرافية وعلمية واسع، وإلى تحوّل ديموغرافي كارثي للسكان الأصليين في القارة والجزر المجاورة.", region:"oceania", theme:"exploration", entity:"gb"},
    {year:1776, label:"1776", title:"إعلان استقلال الولايات المتحدة", body:"في 1776 م أعلنت ثلاثة عشر مستعمرة بريطانية في أمريكا الشمالية استقلالها، وصاغت وثيقة تؤسس الشرعية على حقوق الإنسان وحكم المحكومين. لم يكن الإعلان نهاية الصراع، بل بداية حرب استمرت سنوات حتى الاعتراف بالاستقلال في 1783. أنتجت التجربة أول جمهورية حديثة بدستور مكتوب وفصل سلطات واتحاد فيدرالي، وصارت نموذجاً ومرجعاً لحركات التحرر والثورات في أوروبا وأمريكا اللاتينية لاحقاً.", region:"americas", theme:"politics", entity:"us"},
    {year:1788, label:"1788", title:"الأسطول الأول والاستيطان الأوروبي في أستراليا", body:"في 1788 م وصل الأسطول البريطاني الأول إلى خليج سيدني وأسس مستعمرة عقابية، فبدأ الاستيطان الأوروبي الدائم في أستراليا. لم تكن الأرض خالية، فقد عاشت فيها مجتمعات السكان الأصليين التي دفعتها الموجات الاستيطانية إلى فقدان الأرض والمرض والعنف. شكّل هذا الحدث أساس الدولة الأسترالية الحديثة، وفتح ملفاً طويلاً من الظلم والمطالبات بالعدالة والمصالحة لم يُغلق حتى اليوم.", region:"oceania", theme:"politics", entity:null},
    {year:1789, label:"1789", title:"الثورة الفرنسية", body:"في 1789 م انهارت السلطة الملكية في فرنسا أمام أزمة مالية وغضب اجتماعي، فاجتمع النواب وأعلنوا حقوق الإنسان والمواطن، ثم أطاحوا بالنظام القديم. لم تكن الثورة حدثاً واحداً، بل مساراً من الإصلاح إلى العنف إلى الديكتاتورية ثم إلى إعادة البناء، وأنتجت مفاهيم المواطنة والقانون المدني والتعليم العام. غيّرت أوروبا سياسياً وفكرياً، وأطلقت موجات ثورية وحروباً، وأثبتت أن الشرعية يمكن أن تُؤسس على الأمة لا على الملك.", region:"europe", theme:"politics", entity:"fr"},
    {year:1799, label:"1799", title:"حجر رشيد وفك رموز الهيروغليفية", body:"في 1799 م عثر جنود فرنسيون في مصر على حجر يحمل نصوصاً بثلاث كتابات، فصار مفتاحاً لفهم الهيروغليفية بعد قرون من العجز عن قراءتها. عمل علماء مثل شامبليون على مطابقة الأسماء والأصوات، فأعادوا إلى الحياة لغة وحضارة كاملة كانت مغلقة. لم يكن الاكتشاف أثرياً فقط، بل غيّر فهم العالم لتاريخ مصر وأثّر في علم المصريات وفي فكرة أن النصوص القديمة قابلة للاستعادة بالمنهج لا بالحدس.", region:"africa", theme:"knowledge", entity:"eg"},
    {year:1804, label:"1804", title:"استقلال هايتي", body:"في 1804 م أعلنت هايتي استقلالها بعد ثورة قادها المستعبدون السابقون، فصارت أول دولة تنشأ من ثورة عبيد ناجحة وأول جمهورية سوداء في العالم الحديث. واجهت البلاد حصاراً اقتصادياً وديوناً وعزلة دبلوماسية فرضتها القوى الاستعمارية، فقيّدت مسارها التنموي. رغم ذلك، ألهمت الثورة حركات التحرر في الأمريكتين وأفريقيا، وأثبتت أن العبودية يمكن أن تُهزم، وأن الحرية تُنتزع لا تُمنح.", region:"americas", theme:"rights", entity:null},
    {year:1804, label:"1804", title:"القانون المدني الفرنسي", body:"في 1804 م صدر القانون المدني الفرنسي في عهد نابليون، فوحّد قواعد الملكية والعقود والأسرة والميراث في نص واحد واضح، وأكد المساواة أمام القانون مع احتفاظه بسلطة أبوية قوية. انتشر القانون بالفتح والتبني في أوروبا وأمريكا اللاتينية والشرق، وصار أساس القوانين المدنية في دول كثيرة. أهميته أنه حوّل القانون من تراكم عادات إلى نظام مكتوب ومتسق، وأثبت أن التشريع أداة بناء دولة حديثة.", region:"europe", theme:"rights", entity:"fr"},
    {year:1810, label:"1810", title:"بداية استقلال أمريكا اللاتينية", body:"في 1810 م بدأت في أمريكا اللاتينية انتفاضات ضد الحكم الإسباني، انطلقت من المكسيك وكاراكاس وبوينس آيرس، وقادها قادة مثل بوليفار وسان مارتن وهيدالغو. تأثرت الحركات بالأفكار الليبرالية وبأزمة إسبانيا بعد نابليون، واعتمدت على جيوش محلية وتحالفات بين النخب والفلاحين. أنتجت دولاً مستقلة لكنها واجهت انقسامات داخلية واقتصادات معتمدة على التصدير، وتركت إرثاً من عدم المساواة والصراع على السلطة.", region:"americas", theme:"politics", entity:"mx"},
    {year:1816, label:"1816", title:"شاكا وبناء مملكة الزولو", body:"في 1816 م تولى شاكا حكم مملكة زولو الصغيرة، فحوّلها بالتنظيم العسكري والانضباط والتكتيك إلى قوة إقليمية في جنوب أفريقيا. أدخل تشكيلات قتالية جديدة وسياسة دمج للقبائل المهزومة، وبنى هوية جماعية حول الملك. لم تكن المملكة بلا تكلفة، فقد عرفت عنفاً وتوسعاً دموياً، لكنها أصبحت رمزاً للمقاومة الأفريقية أمام الاستيطان البريطاني والهولندي، وظلّت مركزية في الذاكرة الوطنية بجنوب أفريقيا.", region:"africa", theme:"politics", entity:"za"},
    {year:1839, label:"1839", title:"التنظيمات العثمانية", body:"في 1839 م أعلن السلطان عبد المجيد الأول مرسوماً عُرف بخط شريف كلخانة، يضمن أمن الأرواح والممتلكات والمساواة أمام القانون وتنظيم الضرائب والتجنيد. بدأت بذلك فترة التنظيمات التي أعادت بناء الإدارة والقضاء والتعليم على أسس حديثة، تحت ضغط أوروبي وحاجة داخلية. لم تنجح الإصلاحات في إنقاذ الإمبراطورية، لكنها أنتجت نخبة قانونية وفكرية، وأسّست جدلاً حول العلمانية والهوية استمر في تركيا والمنطقة بعد انهيار الدولة.", region:"middle-east", theme:"rights", entity:"tr"},
    {year:1839, label:"1839", title:"حرب الأفيون الأولى", body:"في 1839 م صادر المسؤول الصيني لين زيكسو شحنات أفيون بريطانية في كانتون، فاندلعت حرب انتهت بهزيمة الصين ومعاهدة نانجينغ التي فتحت موانئ وتنازلت عن هونغ كونغ. لم تكن الحرب تجارية فقط، بل مواجهة بين نظام إمبراطوري مغلق وتوسع رأسمالي بحري. أدت إلى معاهدات غير متكافئة ومناطق نفوذ، وأضعفت أسرة تشينغ، وأطلقت قرناً من التدخل الأجنبي في الصين وحركات إصلاح وثورة لاحقة.", region:"asia", theme:"war", entity:"cn"},
    {year:1848, label:"1848", title:"ثورات 1848 في أوروبا", body:"في 1848 م اجتاحت أوروبا موجة ثورات بدأت في صقلية وباريس ثم انتشرت إلى فيينا وبرلين وبودابست وميلانو، مطالبة بالدساتير والحرية الوطنية وحقوق العمال. فشلت معظمها عسكرياً، لكنها أجبرت الأنظمة على إصلاحات ودفعت إلى توحيد ألمانيا وإيطاليا لاحقاً. كشفت الثورات عن صعود الوعي الوطني والطبقة العاملة، وأثبتت أن الأفكار التي تُهزم في الميدان قد تعود عبر المؤسسات والتعليم في أجيال تالية.", region:"europe", theme:"politics", entity:null},
    {year:1853, label:"1853", title:"سفن بيري تفتح اليابان", body:"في 1853 م وصل أسطول أمريكي بقيادة كومودور بيري إلى خليج إيدو وطالب بفتح الموانئ، فكسر سياسة الانغلاق التي استمرت قرنين وأثار أزمة سياسية في اليابان. أدت المعاهدات اللاحقة إلى انهيار شوغونية توكوغاوا وإلى إصلاحات ميجي التي حوّلت البلاد إلى دولة صناعية مركزية. يُقرأ الحدث كنموذج للصدمة الخارجية التي تُسرّع التحول الداخلي، وكدليل على أن العزلة لم تكن خياراً ممكناً في عالم يتشكل بحرياً.", region:"asia", theme:"politics", entity:"jp"},
    {year:1857, label:"1857", title:"ثورة الهند الكبرى", body:"في 1857 م انطلق تمرد واسع في الهند بدأ بين جنود هنود في الجيش البريطاني، ثم امتد إلى مدن وأرياف وشمل حكاماً محليين وفلاحين. قُمع التمرد بعنف، لكنه أنهى حكم شركة الهند الشرقية ونقل الهند إلى الحكم البريطاني المباشر، وأعاد تنظيم الجيش والإدارة. لم يكن التمرد حركة استقلال منظمة، لكنه صار رمزاً للمقاومة، وأسهم في تشكّل الوعي الوطني الذي نضج لاحقاً في المؤتمر الوطني الهندي.", region:"asia", theme:"war", entity:"in"},
    {year:1859, label:"1859", title:"داروين وأصل الأنواع", body:"في 1859 م نشر تشارلز داروين كتابه أصل الأنواع، مقترحاً أن الكائنات تتغير عبر الانتخاب الطبيعي على مدى أجيال طويلة، وأن التنوع الحيوي نتيجة عملية تاريخية لا تصميم ثابت. أثار الكتاب جدلاً دينياً وعلمياً واسعاً، لكنه أعاد تعريف مكان الإنسان في الطبيعة وأسّس علم الأحياء الحديث. امتد أثره إلى الطب والزراعة وعلم الاجتماع، وظلّ مثالاً على كيف يمكن لفكرة علمية أن تغيّر تصور المجتمع لنفسه وللعالم.", region:"europe", theme:"knowledge", entity:"gb"},
    {year:1861, label:"1861", title:"الحرب الأهلية الأمريكية", body:"في 1861 م بدأت الحرب الأهلية الأمريكية بين الولايات الشمالية والجنوبية، بعد صراع حول العبودية والاتحاد والسلطة الفيدرالية، واستمرت أربع سنوات. انتهت بانتصار الشمال وإلغاء العبودية، لكنها خلّفت مئات الآلاف من القتلى ودماراً في الجنوب، وأعادت تعريف الدستور الاتحادي. لم تحقق المساواة الفعلية للسود، إذ أعقبتها قوانين فصل عنصري استمرت قرناً، لكن الحرب جعلت إلغاء العبودية شرطاً دستورياً لا قضية رأي.", region:"americas", theme:"war", entity:"us"},
    {year:1863, label:"1863", title:"تأسيس الصليب الأحمر", body:"في 1863 م تأسست في جنيف لجنة دولية لإغاثة جرحى الحروب، بعد تجربة هنري دونان في معركة سولفرينو، فصارت نواة الحركة الدولية للصليب الأحمر. طوّرت الحركة قواعد محايدة للعمل الإنساني، وأسهمت في صياغة اتفاقيات جنيف التي تحمي الجرحى والأسرى والمدنيين. مثّل هذا التحول اعترافاً بأن للحرب قيوداً، وأن الرحمة يمكن أن تُنظّم مؤسسياً، وأسّس تقليداً دولياً في القانون الإنساني ما يزال قائماً.", region:"global", theme:"rights", entity:null},
    {year:1868, label:"1868", title:"إصلاح ميجي في اليابان", body:"في 1868 م أطاحت نخبة من الأمراء والساموراي بنظام توكوغاوا وأعلنت استعادة الإمبراطور، فبدأت إصلاحات ميجي التي ألغت الإقطاع وبنَت جيشاً وطنياً وتعليماً عاماً وصناعة حديثة. اعتمدت اليابان على بعثات إلى أوروبا وأمريكا وعلى استيراد التقنية مع الحفاظ على الهوية، فتحوّلت في جيل واحد إلى قوة صناعية وعسكرية. أنتج هذا النموذج نجاحاً باهراً في مواجهة الاستعمار، لكنه دفع البلاد لاحقاً إلى التوسع الإمبريالي في آسيا.", region:"asia", theme:"politics", entity:"jp"},
    {year:1869, label:"1869", title:"افتتاح قناة السويس", body:"في 1869 م افتُتحت قناة السويس التي ربطت البحر المتوسط بالبحر الأحمر، فاختصرت طريق التجارة بين أوروبا وآسيا بآلاف الأميال وأعادت تشكيل خرائط الملاحة العالمية. بُنيت القناة بعمل مصري قسري وأموال وديون أوروبية، وسرعان ما تحولت إلى نقطة نفوذ استراتيجي، إذ اشترت بريطانيا حصة مصر ثم احتلت البلاد في 1882. صارت القناة رمزاً للتبعية المالية والسياسية، ومحوراً في الصراعات الدولية حتى اليوم.", region:"middle-east", theme:"economy", entity:"eg"},
    {year:1870, label:"1870", title:"توحيد ألمانيا", body:"في 1870 م انتصرت بروسيا وحلفاؤها في الحرب الفرنسية البروسية، فأُعلن في فرساي إمبراطورية ألمانية موحدة تحت قيادة بسمارك، بعد سلسلة حروب دبلوماسية ضد الدنمارك والنمسا وفرنسا. جمع التوحيد دولاً ذات سيادة في كيان فيدرالي صناعي وعسكري قوي، وغيّر ميزان القوى الأوروبي. أدى ضعف فرنسا وسقوط نظامها الإمبراطوري إلى جمهورية ثالثة وإلى عداء دائم، فصار التوحيد الألماني أحد أسباب الصراع الذي انفجر في 1914.", region:"europe", theme:"politics", entity:"de"},
    {year:1884, label:"1884", title:"مؤتمر برلين وتقسيم أفريقيا", body:"في 1884 و1885 عقدت القوى الأوروبية مؤتمراً في برلين لوضع قواعد التنافس الاستعماري في أفريقيا، فأُقرّ مبدأ الاحتلال الفعلي وحرية التجارة في حوض الكونغو، وتُرك التقسيم للتفاوض بين الأوروبيين. لم يشارك أي أفريقي في المؤتمر، ورُسمت حدود صناعية لم تراعِ المجتمعات واللغات. أنتج التقسيم دولاً هشة وحدوداً مثقلة بالصراعات، وأسّس لاستغلال اقتصادي واسع، وظلّ أحد أعمق أسباب عدم الاستقرار في القارة.", region:"africa", theme:"politics", entity:null},
    {year:1893, label:"1893", title:"نيوزيلندا تمنح النساء حق التصويت", body:"في 1893 م صارت نيوزيلندا أول دولة في العالم تمنح النساء حق التصويت على المستوى الوطني، بعد حملات نظمتها حركات نسائية وقيادات مثل كيت شيبارد. جاء التصويت في مستعمرة تتمتع بحكم ذاتي وحركة إصلاحية نشطة، وأثار نقاشاً عالمياً حول المواطنة الكاملة. انتشر الحق لاحقاً في دول أخرى بسرعات متفاوتة، وظلّت الحادثة علامة على أن الإصلاح السياسي يمكن أن يبدأ من أطراف صغيرة قبل أن يصبح معياراً دولياً.", region:"oceania", theme:"rights", entity:null},
    {year:1896, label:"1896", title:"معركة عدوة", body:"في 1896 م انتصر الجيش الإثيوبي بقيادة منليك الثاني في عدوة على قوة إيطالية غازية، فمنع احتلال البلاد وأجبر إيطاليا على الاعتراف بالسيادة الإثيوبية. لم يكن الانتصار عسكرياً فقط، بل ثمرة توحيد سياسي وتعبئة وطنية وتسليح مدروس. صار عدوة رمزاً عالمياً للمقاومة الأفريقية ضد الاستعمار، وواحداً من قلائل الحالات التي حفظت فيها دولة أفريقية استقلالها في زمن التقسيم، وأثّر في حركات التحرر لاحقاً.", region:"africa", theme:"war", entity:"et"},
    {year:1901, label:"1901", title:"اتحاد أستراليا", body:"في 1901 م توحدت المستعمرات البريطانية الست في أستراليا في اتحاد فيدرالي واحد، بعد استفتاءات ومساومات بين المستعمرات حول الضرائب والهجرة والسكك. أنشأ الاتحاد برلماناً ودستوراً ومواطنة، لكنه استند إلى سياسة أستراليا البيضاء التي استبعدت المهاجرين الآسيويين، وإلى تجاهل حقوق السكان الأصليين. مثّل الاتحاد نموذجاً للانتقال من الاستعمار إلى الدولة الحديثة داخل الكومنولث، وترك إرثاً من الأسئلة حول الهوية والعدالة.", region:"oceania", theme:"politics", entity:null},
    {year:1904, label:"1904", title:"الحرب الروسية اليابانية", body:"في 1904 م بدأت حرب بين روسيا واليابان حول منشوريا وكوريا، وانتهت بانتصار ياباني واضح في معركة تسوشيما ومعاهدة بورتسموث في 1905. كانت أول حرب حديثة تنتصر فيها دولة آسيوية على قوة أوروبية كبرى، فاهتزت أسطورة التفوق الأوروبي وأثارت صدى واسعاً في المستعمرات. أضعفت الحرب النظام القيصري ومهّدت لثورة 1905، وشجعت الحركات الوطنية في آسيا، لكنها رسّخت أيضاً طموحات اليابان الإمبريالية التي قادت إلى حروب لاحقة.", region:"asia", theme:"war", entity:"jp"},
    {year:1911, label:"1911", title:"ثورة شينهاي", body:"في 1911 م انطلقت انتفاضة في ووهان ثم انتشرت في الصين، فسقطت أسرة تشينغ بعد قرون من الحكم الإمبراطوري وأُعلنت الجمهورية في 1912. لم تكن الثورة نتيجة تنظيم واحد، بل تجمعاً لتيارات إصلاحية وثورية وغضب ضد الضعف الخارجي. أنهت الثورة نظاماً سياسياً عمره أكثر من ألفي سنة، لكنها لم تحقق وحدة وطنية، فدخلت الصين عقوداً من الانقسام والحكم العسكري والصراع على السلطة قبل قيام جمهورية الصين الشعبية في 1949.", region:"asia", theme:"politics", entity:"cn"},
    {year:1914, label:"1914", title:"الحرب العالمية الأولى", body:"في 1914 م انفجرت الحرب العالمية الأولى بعد أزمة سراييفو، فسحبت تحالفات أوروبا القارية دولاً عدة إلى صراع لم يشهده العالم من قبل. استخدمت المدفعية والخنادق والغاز والطائرات، ومات ملايين الجنود في جبهات ثابتة، وانهارت أربع إمبراطوريات في نهايتها. لم تكن الحرب أوروبية فقط، بل امتدت إلى الشرق الأوسط وأفريقيا وآسيا عبر المستعمرات. أعادت رسم الخرائط وأنتجت عصبة الأمم، وتركت جرحاً سياسياً ونفسياً مهّد لحرب ثانية.", region:"europe", theme:"war", entity:null},
    {year:1915, label:"1915", title:"غاليبولي وذاكرة أنزاك", body:"في 1915 م شنّت قوات بريطانية وفرنسية وأسترالية ونيوزيلندية إنزالاً على شبه جزيرة غاليبولي لاحتلال المضائق العثمانية، لكن الحملة فشلت بعد أشهر من القتال العنيف والانسحاب. رغم الهزيمة، صار يوم الإنزال محوراً لهوية أستراليا ونيوزيلندا الوطنية، إذ شكّل التضحية المشتركة وعياً بالذات بعيداً عن بريطانيا. تحوّل الموقع إلى نصب للذاكرة والمصالحة، ويُستخدم اليوم للتأمل في كلفة الحرب وفي العلاقة بين المستعمرات السابقة والأمبراطورية.", region:"oceania", theme:"war", entity:null},
    {year:1917, label:"1917", title:"الثورة البلشفية في روسيا", body:"في 1917 م أطاحت ثورة فبراير بالقيصر، ثم قاد البلاشفة بزعامة لينين ثورة أكتوبر واستولوا على السلطة بشعارات السلام والخبز والأرض. أنهت الثورة النظام القيصري، وأخرجت روسيا من الحرب، وأطلقت حرباً أهلية وحكماً واحداً وإصلاحات زراعية وصناعية قاسية. أنشأت أول دولة شيوعية، فصارت نموذجاً لحركات في آسيا وأفريقيا وأمريكا اللاتينية، ومصدر قلق للقوى الرأسمالية طوال القرن العشرين.", region:"europe", theme:"politics", entity:"ru"},
    {year:1922, label:"1922", title:"استقلال مصر الشكلي", body:"في 1922 م أعلنت بريطانيا إنهاء الحماية وإعلان مصر مملكة مستقلة، بعد ثورة 1919 وضغط وطني واسع، لكنها احتفظت بقواعد عسكرية وسيطرة على السودان وحماية المصالح الأجنبية. لم يكن الاستقلال كاملاً، فاستمر النضال من أجل الجلاء وتعديل المعاهدات وصياغة دستور. أنتجت المرحلة أحزاباً وبرلماناً وصحافة نشطة وحركة نسائية، وأثبتت أن الاستقلال القانوني بلا سيادة فعلية يظل ناقصاً، وهو درس تكرر في مستعمرات أخرى.", region:"africa", theme:"politics", entity:"eg"},
    {year:1923, label:"1923", title:"قيام الجمهورية التركية", body:"في 1923 م أُعلنت الجمهورية التركية بعد حرب الاستقلال، وانتخب مصطفى كمال أتاتورك رئيساً، فبدأت إصلاحات جذرية فصلت الدين عن الدولة وألغت الخلافة وبدّلت الحرف والأزياء والقانون. هدفت الإصلاحات إلى بناء دولة قومية حديثة قادرة على النجاة في نظام دولي جديد، ونُفّذت بسلطة مركزية قوية وبتكلفة على المعارضة والتنوع الثقافي. صارت تركيا نموذجاً مثيراً للجدل في التحديث من فوق، وفي العلاقة بين الإسلام والعلمانية والدولة القومية.", region:"middle-east", theme:"politics", entity:"tr"},
    {year:1932, label:"1932", title:"توحيد المملكة العربية السعودية", body:"في 1932 م أُعلن توحيد المملكة العربية السعودية بعد سلسلة حملات بدأت في أوائل القرن، جمعت نجد والحجاز والأحساء ومناطق أخرى تحت سلطة واحدة. قامت الدولة على تحالف تاريخي بين القيادة السياسية والدعوة الدينية، وعلى مؤسسات قبلية وإدارية أعيد تنظيمها. أدى اكتشاف النفط في 1938 إلى تحوّل اقتصادي عميق وغيّر موقع المملكة دولياً، فصارت لاعباً مركزياً في أسواق الطاقة والسياسة الإقليمية والعالمية.", region:"middle-east", theme:"politics", entity:"sa"},
    {year:1939, label:"1939", title:"الحرب العالمية الثانية", body:"في 1939 م بدأت الحرب العالمية الثانية بغزو ألمانيا النازية لبولندا، فامتدت من أوروبا إلى أفريقيا وآسيا والمحيط الهادئ، وشملت جرائم إبادة جماعية وقصفاً للمدن واستخدام السلاح النووي. انتهت في 1945 بانتصار الحلفاء وهزيمة ألمانيا واليابان، وبملايين القتلى ودمار واسع. أنتجت الأمم المتحدة ونظاماً دولياً جديداً، وأدت إلى انقسام أوروبا وبداية الحرب الباردة، وإلى إنهاء الاستعمار تدريجياً في آسيا وأفريقيا.", region:"europe", theme:"war", entity:null},
    {year:1945, label:"1945", title:"قصف هيروشيما وناغازاكي", body:"في أغسطس 1945 م أسقطت الولايات المتحدة قنبلتين ذريتين على هيروشيما وناغازاكي، فقتلت عشرات الآلاف فوراً وأكثر منهم لاحقاً بالإشعاع، وأعلنت اليابان استسلامها بعد أيام. أنهى القصف الحرب في آسيا، لكنه فتح عصراً نووياً غيّر مفهوم الأمن والردع، وأثار جدلاً أخلاقياً مستمراً حول شرعية الأسلحة الشاملة. صارت المدن رمزاً عالمياً لكلفة التقنية بلا ضوابط، ومحرّضاً على حركات نزع السلاح النووي ومعاهدات الحد من الانتشار.", region:"asia", theme:"war", entity:"jp"},
    {year:1945, label:"1945", title:"تأسيس الأمم المتحدة", body:"في 1945 م وُقّع ميثاق الأمم المتحدة في سان فرانسيسكو بمشاركة خمسين دولة، فقامت منظمة دولية بديلة لعصبة الأمم بهدف حفظ السلم وحقوق الإنسان والتعاون الاقتصادي. منحت هيكلتها حق النقض للقوى الكبرى، ما جعل قراراتها تعكس توازن القوى أكثر مما تعكس العدالة المطلقة. رغم عجزها عن منع حروب كثيرة، فقد أنشأت وكالات للإغاثة والصحة والتعليم والقانون الدولي، وأصبحت منبراً أساسياً للشرعية الدولية وحركات التحرر.", region:"global", theme:"politics", entity:null},
    {year:1947, label:"1947", title:"استقلال الهند وتقسيمها", body:"في 1947 م نالت الهند استقلالها عن بريطانيا، لكن البلاد قُسمت إلى الهند وباكستان على أساس ديني، فهاجر ملايين وقتل مئات الآلاف في أعمال عنف طائفية. أنهى التقسيم إمبراطورية بريطانية شاسعة، وأسّس دولتين لهما هويتان متصارعتان، وترك كشمير نزاعاً مفتوحاً. جاء الاستقلال بعد عقود من النضال المدني بقيادة غاندي ونهرو وجمعية مسلمي الهند، وأثبت أن التحرر من الاستعمار قد يحمل ثمناً باهظاً في التنوع الاجتماعي.", region:"asia", theme:"politics", entity:"in"},
    {year:1948, label:"1948", title:"قيام دولة إسرائيل والنكبة", body:"في 1948 م أُعلنت دولة إسرائيل عند انتهاء الانتداب البريطاني على فلسطين، فاندلعت حرب بين الدول العربية وإسرائيل، وهاجر أو طُرد نحو سبعمئة ألف فلسطيني فيما يُعرف بالنكبة. لم ينته الصراع بعد ذلك، بل أنتج سلسلة حروب وانتفاضات ومفاوضات ومخيمات لاجئين. ظلّت القضية الفلسطينية محوراً في السياسة العربية والإسلامية، وفي القانون الدولي، وفي نقاش عالمي حول حق تقرير المصير واللاجئين والحدود.", region:"middle-east", theme:"politics", entity:null},
    {year:1948, label:"1948", title:"تأسيس نظام الأبارتايد", body:"في 1948 م وصل الحزب الوطني في جنوب أفريقيا إلى الحكم وبدأ تطبيق سياسة الأبارتايد، وهي نظام فصل عنصري شامل يقيّد السود في الإقامة والتعليم والعمل والتنقل والمواطنة. لم يكن النظام مجرد تمييز عرفي، بل بنية قانونية واقتصادية استفادت منها أقلية، وواجهته مقاومة من المؤتمر الوطني الأفريقي ونقابات وكنائس. استمر عقوداً، وعُزلت البلاد دولياً، حتى أُلغي في أوائل التسعينيات بعد ضغط داخلي وخارجي وانتقال تفاوضي.", region:"africa", theme:"rights", entity:"za"},
    {year:1949, label:"1949", title:"قيام جمهورية الصين الشعبية", body:"في 1949 م أعلن ماو تسي تونغ قيام جمهورية الصين الشعبية بعد انتصار الشيوعيين في الحرب الأهلية، وانسحبت حكومة الكومينتانغ إلى تايوان. أعاد النظام توزيع الأرض، ثم نفّذ تصنيعاً سريعاً وتعاونيات زراعية وحملات سياسية واسعة، بعضها تسبب في مجاعة وخسائر بشرية كبيرة. أعادت الصين توحيد معظم أراضيها كدولة مركزية قوية، وتبنّت نموذجاً تنموياً مستقلاً، ثم انتقلت بعد 1978 إلى إصلاحات سوقية غيّرت الاقتصاد العالمي.", region:"asia", theme:"politics", entity:"cn"},
    {year:1956, label:"1956", title:"تأميم قناة السويس والعدوان الثلاثي", body:"في 1956 م أعلن جمال عبد الناصر تأميم شركة قناة السويس لتمويل سد أسوان، فردت بريطانيا وفرنسا وإسرائيل بهجوم عسكري، ثم انسحبت تحت ضغط أمريكي وسوفي وأممي. مثّل الحدث نهاية النفوذ الاستعماري القديم في المنطقة، وصعود القومية العربية وزعامة ناصر، وبروز الأمم المتحدة كإطار لموازين الحرب الباردة. كما رسّخ فكرة أن السيطرة على الممرات المائية قضية سيادية، وأسهم في تشكيل سياسات عدم الانحياز.", region:"middle-east", theme:"war", entity:"eg"},
    {year:1960, label:"1960", title:"عام أفريقيا", body:"في 1960 م نالت سبع عشرة دولة أفريقية استقلالها، في أكبر موجة تحرر في القارة، فصار العام يُعرف بعام أفريقيا. جاء الاستقلال بعد ضغط حركات وطنية ونقابات وطلاب، وبعد تغيّر موازين القوى بعد الحرب العالمية الثانية. لكن الدول الجديدة ورثت حدوداً استعمارية واقتصادات أحادية المحصول ومؤسسات هشة، فدخلت كثير منها في صراعات وانقلابات وتبعية اقتصادية. ظلّت هذه الموجة نقطة مرجعية في تاريخ القارة وفي سياسات الهوية والتنمية.", region:"africa", theme:"politics", entity:null},
    {year:1962, label:"1962", title:"أزمة الصواريخ الكوبية", body:"في 1962 م نشر الاتحاد السوفييتي صواريخ نووية في كوبا رداً على صواريخ أمريكية في تركيا، ففرضت واشنطن حصاراً بحرياً وبلغ العالم حافة حرب نووية. انتهت الأزمة باتفاق سحب الصواريخ مقابل تعهد بعدم غزو كوبا وسحب صواريخ من تركيا سراً. كانت أخطر لحظة في الحرب الباردة، وأنتجت قنوات اتصال مباشرة بين القوتين ومعاهدات للحد من التجارب النووية، وأثبتت أن الردع يعمل بشرط وجود مصالح مشتركة في تجنب الكارثة.", region:"americas", theme:"politics", entity:null},
    {year:1969, label:"1969", title:"هبوط الإنسان على القمر", body:"في 1969 م هبطت مركبة أبولو 11 على سطح القمر، وخطا نيل أرمسترونغ أول خطوة بشرية هناك، في ذروة سباق فضائي بين الولايات المتحدة والاتحاد السوفييتي. لم يكن الإنجاز علمياً فقط، بل نتيجة استثمار ضخم في الصواريخ والحواسيب والمواد والتنظيم، ورمزاً للتفوق التقني في الحرب الباردة. أنتج البرنامج تقنيات انتقلت إلى الحياة اليومية، وأعاد تعريف حدود الممكن، وأطلق نقاشاً حول مكان الأرض في الكون وكلفة الاستكشاف.", region:"global", theme:"technology", entity:"us"},
    {year:1973, label:"1973", title:"أزمة النفط العالمية", body:"في 1973 م خفضت الدول العربية المصدرة للنفط الإنتاج وحظرت التصدير إلى دول دعمت إسرائيل في حرب أكتوبر، فارتفعت الأسعار بأكثر من ثلاثة أضعاف وتغيّرت خرائط الاقتصاد العالمي. كشفت الأزمة اعتماد الصناعات الغربية على الطاقة المستوردة، وأدت إلى تضخم وتباطؤ وانتقال في الثروة نحو المنتجين. دعمت الأزمة مشاريع تنموية في الخليج، وأطلقت نقاشاً حول أمن الطاقة والبدائل، وربطت أسواق النفط بالسياسة الدولية بشكل دائم.", region:"middle-east", theme:"economy", entity:"sa"},
    {year:1975, label:"1975", title:"نهاية حرب فيتنام", body:"في 1975 م سقطت سايغون بيد قوات شمال فيتنام، فانتهت حرب استمرت نحو عشرين سنة وأسفرت عن ملايين القتلى ودمار واسع. كانت الحرب أول هزيمة عسكرية واضحة للولايات المتحدة في الحرب الباردة، وأثارت حركات احتجاج طلابية واسعة غيّرت الثقافة السياسية الغربية. توحّدت فيتنام تحت نظام شيوعي، ثم انتقلت في 1986 إلى إصلاحات سوقية فتحت الاقتصاد، فأصبحت من أسرع الاقتصادات نمواً في آسيا، في تحوّل يلخّص مرونة الدولة الحزبية أمام الفشل الاقتصادي.", region:"asia", theme:"war", entity:"vn"},
    {year:1979, label:"1979", title:"الثورة الإيرانية", body:"في 1979 م انهارت الملكية الإيرانية أمام احتجاجات واسعة قادها رجال دين وطلاب وعمال، وعاد الخميني من المنفى ليؤسس جمهورية إسلامية تقوم على ولاية الفقيه. أنهت الثورة نظاماً موالياً للغرب، وأعادت تشكيل سياسة الخليج والشرق الأوسط، وأثّرت في حركات إسلامية في المنطقة والعالم. واجهت الدولة حرباً مع العراق وحصاراً وعزلة، وطورت برنامجاً نووياً مثيراً للجدل، بينما شهد الداخل صراعاً بين تيارات محافظة وإصلاحية.", region:"middle-east", theme:"politics", entity:"ir"},
    {year:1989, label:"1989", title:"سقوط جدار برلين", body:"في 1989 م فُتح جدار برلين بعد احتجاجات جماهيرية في ألمانيا الشرقية وتراجع الدعم السوفييتي، فتدفق الناس بين الشطرين، وأصبح الحدث رمزاً لنهاية الانقسام الأوروبي. سبقته إصلاحات غورباتشوف وحركات تضامن في بولندا والمجر وتشيكوسلوفاكيا. أدى سقوط الجدار إلى توحيد ألمانيا في 1990 وإلى تفكك حلف وارسو، فغيّر خريطة أوروبا وميزان القوى الدولي، وأطلق نقاشاً حول الديمقراطية والانتقال الاقتصادي في أوروبا الشرقية.", region:"europe", theme:"politics", entity:"de"},
    {year:1991, label:"1991", title:"تفكك الاتحاد السوفييتي", body:"في 1991 م أُعلن حل الاتحاد السوفييتي بعد انقلاب فاشل واستقلال الجمهوريات، فانتهت دولة عظمى استمرت سبعين سنة وانتهت الحرب الباردة رسمياً. أدى التفكك إلى أزمة اقتصادية واجتماعية حادة في روسيا والجمهوريات، وإلى صعود أوليغارشية وصراعات حدودية، وإلى تحولات جذرية في أوروبا الشرقية. أنتج نظاماً دولياً أحادي القطب نسبياً بقيادة الولايات المتحدة، لكنه ترك فراغات قوة وصراعات هوية ما تزال تؤثر في السياسة العالمية.", region:"europe", theme:"politics", entity:"ru"},
    {year:1994, label:"1994", title:"نهاية الأبارتايد وانتخاب مانديلا", body:"في 1994 م جرت أول انتخابات متعددة الأعراق في جنوب أفريقيا، وفاز نيلسون مانديلا والمؤتمر الوطني الأفريقي، فانتهى نظام الأبارتايد رسمياً. جاء التحول بعد عقود من المقاومة والإضرابات والعقوبات الدولية وضغط داخلي، وبعد مفاوضات مع حكومة دي كليرك. اختيرت لجنة للحقيقة والمصالحة بدل محاكمات شاملة، فأنتجت اعترافات علنية ومسامحة سياسية. ظلّ التفاوت الاقتصادي والعرقي عميقاً، لكن التجربة صارت مرجعاً في الانتقال السلمي.", region:"africa", theme:"rights", entity:"za"},
    {year:1994, label:"1994", title:"الإبادة في رواندا", body:"في 1994 م قُتل نحو ثمانمئة ألف شخص في رواندا خلال نحو مئة يوم، معظمهم من التوتسي ومن معتدلين من الهوتو، بعد تحريض إعلامي وتنظيم ميليشيات وانهيار مؤسسات الدولة. عجز المجتمع الدولي عن التدخل، وكشفت الحادثة حدود بعثات حفظ السلام وازدواجية المعايير. أنشأت الأمم المتحدة محكمة جنائية دولية لرواندا، وساهمت التجربة في تطوير مفهوم مسؤولية الحماية، وفي نقاش أوسع حول العدالة الانتقالية والذاكرة في منطقة البحيرات الكبرى.", region:"africa", theme:"war", entity:null},
    {year:2001, label:"2001", title:"هجمات 11 سبتمبر", body:"في 2001 م اختطف منفذون تابعون لتنظيم القاعدة أربع طائرات، فدمّروا برجي مركز التجارة العالمي في نيويورك وأصابوا البنتاغون، وقتل نحو ثلاثة آلاف شخص. أدت الهجمات إلى غزو أفغانستان ثم العراق، وإلى إعادة تنظيم الأمن والمراقبة في دول كثيرة، وإلى نقاش حول الإرهاب والدين والحريات المدنية. غيّرت السياسة الخارجية الأمريكية لعقدين، وأسست إطاراً عالمياً لمكافحة الإرهاب، وربطت بين الشرق الأوسط والأمن الدولي بعمق أكبر.", region:"global", theme:"politics", entity:null},
    {year:2004, label:"2004", title:"تسونامي المحيط الهندي", body:"في 2004 م وقع زلزال بحري قوي قبالة سومطرة، فأطلق موجات مد عاتية ضربت إندونيسيا وسريلانكا والهند وتايلاند ودولاً أفريقية، وقتل نحو مئتي ألف شخص. كشفت الكارثة غياب أنظمة إنذار مبكر في المحيط الهندي، وضعف التنسيق الدولي، فأنشئت شبكات إنذار إقليمية بعدها. كما أظهرت موجة تضامن عالمية غير مسبوقة في التبرعات والإغاثة، وأعادت فتح نقاش حول إعادة الإعمار والعدالة في توزيع المساعدات والاستعداد للكوارث.", region:"asia", theme:"environment", entity:"id"},
    {year:2008, label:"2008", title:"الأزمة المالية العالمية", body:"في 2008 م انهار بنك ليمان براذرز بعد أزمة قروض عقارية عالية المخاطر، فانتشرت الأزمة من الولايات المتحدة إلى الأسواق العالمية، ودخلت اقتصادات كبيرة في ركود. تدخلت الحكومات بخطط إنقاذ وتيسير نقدي وتنظيم مالي جديد، لكن البطالة والديون والتفاوت ارتفعت في دول عدة. كشفت الأزمة ترابط النظام المالي وضعف الرقابة، وأضعفت ثقة المواطنين بالمؤسسات، وأسهمت في صعود حركات سياسية احتجاجية وشعبوية في أوروبا وأمريكا.", region:"global", theme:"economy", entity:null},
    {year:2011, label:"2011", title:"الربيع العربي", body:"في 2011 م انطلقت احتجاجات واسعة في تونس ومصر وليبيا وسوريا واليمن والبحرين، مطالبة بالحرية والكرامة والعدالة الاجتماعية ومحاربة الفساد. أسقطت بعض الأنظمة بسرعة، لكن مسارات أخرى انتهت إلى حروب أهلية وتدخلات خارجية وانهيار مؤسسات. كشف الربيع العربي هشاشة الدولة العربية أمام أزمات الشرعية والاقتصاد، وأظهر قدرة الشبكات الرقمية على التعبئة، كما أثار نقاشاً حول الديمقراطية والانتقالات والاستقرار في المنطقة.", region:"middle-east", theme:"politics", entity:null},
    {year:2015, label:"2015", title:"اتفاق باريس للمناخ", body:"في 2015 م تبنّى مؤتمر المناخ في باريس اتفاقاً عالمياً يهدف إلى إبقاء ارتفاع الحرارة دون درجتين مئويتين، مع التزامات وطنية طوعية ومراجعة دورية. جاء الاتفاق بعد عقود من المفاوضات وضغوط علمية متزايدة، وشمل تمويلاً للدول الفقيرة للتكيّف. لم يكن كافياً لوقف الاحترار، لكنه أنشأ إطاراً عالمياً للمحاسبة والشفافية، وحوّل المناخ من قضية بيئية إلى ملف سياسي واقتصادي مركزي.", region:"global", theme:"environment", entity:null},
    {year:2020, label:"2020", title:"جائحة كوفيد-19", body:"في 2020 م أعلنت منظمة الصحة العالمية أن فيروس كورونا المستجد جائحة عالمية، فأُغلقت الحدود والمدارس والأسواق، وتوقفت سلاسل الإمداد، وتوفي ملايين الأشخاص. أظهرت الجائحة تفاوتاً حاداً في القدرة على التلقيح والحماية، وسرّعت التحول الرقمي والعمل عن بعد والتجارة الإلكترونية. كما أعادت طرح أسئلة حول صلاحيات الدولة والحريات المدنية والثقة في العلم والمؤسسات، وتركت آثاراً اقتصادية ونفسية طويلة الأمد في معظم المجتمعات.", region:"global", theme:"environment", entity:null},
    {year:2022, label:"2022", title:"الغزو الروسي لأوكرانيا", body:"في 2022 م شنّت روسيا هجوماً عسكرياً واسعاً على أوكرانيا، فاندلعت أكبر حرب في أوروبا منذ 1945، مع قتلى وتهجير ملايين وتدمير مدن. فرض الغرب عقوبات اقتصادية غير مسبوقة، وارتفعت أسعار الطاقة والغذاء عالمياً، وتعززت مكانة حلف الناتو. أعادت الحرب طرح أسئلة حول السيادة والحدود والأمن الأوروبي والقانون الدولي، وأظهرت اعتماد العالم على سلاسل إمداد هشة، وربطت بين الصراع العسكري والأمن الغذائي والطاقة.", region:"europe", theme:"war", entity:"ua"},
    {year:2022, label:"2022", title:"انتشار الذكاء الاصطناعي التوليدي", body:"في 2022 م أطلقت شركات نماذج لغوية وبصرية توليدية أصبحت متاحة للجمهور، فتحوّل الذكاء الاصطناعي من بحث متخصص إلى أداة يومية في التعليم والعمل والإعلام. أثار الانتشار السريع نقاشاً حول حقوق المؤلف والخصوصية والتحيز والوظائف، ودعا حكومات إلى تنظيم جديد. لم تكن التقنية جديدة تماماً، لكن سهولة الوصول إليها غيّرت شروط إنتاج المعرفة، وجعلت السؤال عن المسؤولية والشفافية والثقة في المحتوى المولّد سؤالاً عاماً لا تقنياً فقط.", region:"global", theme:"technology", entity:null}
  );
})();
